        ["Exportieren"] = "Export",
        ["Adresse des Zeitstempeldienstes"] = "Address of the time-stamping service",
        ["Adresse des Zeitstempeldienstes, z. B. vom Anbieter Ihres Zertifikats"] = "Address of the time-stamping service, e.g. from the provider of your certificate",
        ["Bitte die Adresse eines Zeitstempeldienstes eingeben (beginnt mit http:// oder https://). Ohne gültige Adresse wird ohne Zeitstempel signiert."] = "Please enter the address of a time-stamping service (starting with http:// or https://). Without a valid address, signatures get no time stamp.",
        ["Den Zeitstempeldienst kennt dieser Rechner nicht als vertrauenswürdig."] = "This computer does not know the time-stamping service as trustworthy.",
        ["Der Dienst antwortet: {0}, Zeit {1}."] = "The service answers: {0}, time {1}.",
        ["Der Zeitstempel passt nicht zu dieser Signatur."] = "The time stamp does not match this signature.",
        ["Der Zeitstempeldienst hat die Anfrage abgelehnt ({0})."] = "The time-stamping service refused the request ({0}).",
        ["Der Zeitstempeldienst hat keinen gültigen Zeitstempel geliefert."] = "The time-stamping service did not deliver a valid time stamp.",
        ["Das Zertifikat „{0}“ ist gesperrt (Auskunft der Zertifizierungsstelle)."] = "The certificate “{0}” is revoked (answer of the certification authority).",
        ["Das Zertifikat „{0}“ ist gesperrt (Sperrliste der Zertifizierungsstelle)."] = "The certificate “{0}” is revoked (revocation list of the certification authority).",
        ["Gefragt werden nur die Stellen, die im Zertifikat stehen. Beim eigenen Zertifikat gibt es niemanden zu fragen. Am besten zusammen mit einem Zeitstempel."] = "Only the authorities named in the certificate are asked. For the own certificate there is nobody to ask. Best combined with a time stamp.",
        ["Langzeitprüfung"] = "Long-term validation",
        ["Langzeitprüfung verwenden"] = "Use long-term validation",
        ["Nach dem Unterschreiben fragt PDF-Knead bei der Zertifizierungsstelle nach, ob das Zertifikat gültig ist, und legt die Antwort mit in die Datei. So lässt sich die Unterschrift auch in vielen Jahren noch prüfen, wenn die Stelle nicht mehr antwortet. Gesendet wird nur die Seriennummer des Zertifikats."] = "After signing, PDF-Knead asks the certification authority whether the certificate is valid and puts the answer into the file. The signature can then still be checked in many years, when the authority no longer answers. Only the serial number of the certificate is sent.",
        ["Nicht unterschrieben: {0}"] = "Not signed: {0}",
        ["Sperrstatus der Zertifikate mit in die Datei legen (braucht eine Internetverbindung)"] = "Put the revocation status of the certificates into the file (needs an internet connection)",
        ["Sperrstatus eingebettet — auch später ohne Verbindung prüfbar"] = "revocation status embedded — checkable later without a connection",
        ["Gespeichert. Die Datei war zusätzlich gegen Veränderung geschützt (Integritätsschutz nach ISO/TS 32004). Diesen Schutz kann PDF-Knead noch nicht erneuern — die Datei ist weiter verschlüsselt, aber ohne ihn."] = "Saved. The file was also protected against changes (integrity protection per ISO/TS 32004). PDF-Knead cannot renew this protection yet — the file is still encrypted, but without it.",
        ["Gespeichert. Die Datei war zusätzlich gegen Veränderung geschützt (Integritätsschutz nach ISO/TS 32004). Die Kopie ist ohne Verschlüsselung und ohne diesen Schutz."] = "Saved. The file was also protected against changes (integrity protection per ISO/TS 32004). The copy is without encryption and without this protection.",
        ["Unterschrieben, aber ohne vollständige Langzeitprüfung: für {0} war kein Sperrstatus zu bekommen (keine Verbindung oder die Zertifizierungsstelle antwortet nicht)."] = "Signed, but without complete long-term validation: no revocation status could be obtained for {0} (no connection, or the certification authority does not answer).",
        ["laut eingebetteter Auskunft gesperrt"] = "revoked according to the embedded answer",
        ["unvollständig — nicht für jedes Zertifikat ein Sperrstatus in der Datei"] = "incomplete — not every certificate has a revocation status in the file",
        ["Anmelden"] = "Log in",
        ["Anmeldung beim Dienst (nur bei kostenpflichtigen Diensten)"] = "Login at the service (only for paid services)",
        ["Benutzername"] = "User name",
        ["Benutzername beim Zeitstempeldienst"] = "User name at the time-stamping service",
        ["Das Kundenzertifikat für den Zeitstempeldienst lässt sich nicht verwenden: {0}"] = "The customer certificate for the time-stamping service cannot be used: {0}",
        ["Das Kundenzertifikat für den Zeitstempeldienst lässt sich nicht öffnen: falsches Passwort, oder die Datei ist beschädigt."] = "The customer certificate for the time-stamping service cannot be opened: wrong password, or the file is damaged.",
        ["Das Passwort des Kundenzertifikats stimmt nicht, oder die Datei ist beschädigt."] = "The password of the customer certificate is wrong, or the file is damaged.",
        ["Der Zeitstempeldienst hat die Anmeldung abgelehnt."] = "The time-stamping service refused the login.",
        ["Der Zeitstempeldienst verlangt eine Anmeldung (Benutzername oder Kundenzertifikat in „Zertifikat“ eintragen)."] = "The time-stamping service requires a login (enter a user name or customer certificate in “Certificate”).",
        ["Die Datei enthält kein Zertifikat mit Schlüssel."] = "The file holds no certificate with a key.",
        ["Die Zugangsdaten gibt der Anbieter mit dem Vertrag. Passwörter fragt PDF-Knead beim ersten Unterschreiben nach dem Start und merkt sie nur bis zum Beenden. Anmeldung nur über https."] = "The provider gives the access data with the contract. PDF-Knead asks for passwords at the first signature after starting and keeps them only until it is closed. Login only over https.",
        ["Kundenzertifikat"] = "Customer certificate",
        ["Kundenzertifikat für den Zeitstempeldienst"] = "Customer certificate for the time-stamping service",
        ["Kundenzertifikat wählen"] = "Choose customer certificate",
        ["Mit Anmeldung nur über eine https-Adresse: über http wäre das Passwort unterwegs lesbar."] = "With a login only over an https address: over http the password could be read on the way.",
        ["Nicht geprüft: die Anmeldung ließ sich nicht vorbereiten (Passwort nicht eingegeben oder Kundenzertifikat nicht lesbar)."] = "Not checked: the login could not be prepared (no password entered, or the customer certificate cannot be read).",
        ["Passwort für {0} bei {1} — bis zum Beenden gemerkt"] = "Password for {0} at {1} — kept until closing",
        ["Passwort für {0} — bis zum Beenden gemerkt"] = "Password for {0} — kept until closing",
        ["Zeitstempeldienst"] = "Time-stamping service",
        ["leer, wenn der Dienst keinen verlangt"] = "empty if the service does not require one",
        ["leer, wenn der Dienst keines verlangt"] = "empty if the service does not require one",
        ["Abgebrochen — die bisherige Liste bleibt."] = "Cancelled — the previous list stays.",
        ["Aussteller nicht als qualifizierter Anbieter geführt"] = "issuer not listed as a qualified provider",
        ["Das Zertifikat nennt sich qualifiziert, die EU-Vertrauensliste führt den Aussteller zur Unterschriftszeit aber nicht als qualifizierten Anbieter."] = "The certificate calls itself qualified, but the EU trusted list does not list its issuer as a qualified provider at the time of signing.",
        ["Der Server antwortet mit {0}."] = "The server answers with {0}.",
        ["Die Datei ist keine Vertrauensliste."] = "The file is not a trusted list.",
        ["Die EU und ihre Länder veröffentlichen, welche Anbieter qualifizierte Zertifikate und Zeitstempel ausgeben dürfen. Mit der Liste zeigt die Prüfung, ob eine Signatur wirklich qualifiziert ist (sie ersetzt dann die handschriftliche Unterschrift)."] = "The EU and its countries publish which providers may issue qualified certificates and time stamps. With the list, the check shows whether a signature is really qualified (it then replaces the handwritten signature).",
        ["Die Gesamtliste der EU ist keine Liste der Listen."] = "The EU list is not a list of lists.",
        ["Die Liste der qualifizierten Vertrauensdiensteanbieter der EU laden: dann zeigt die Prüfung, ob eine Signatur qualifiziert ist."] = "Load the EU list of qualified trust service providers: the check then shows whether a signature is qualified.",
        ["Die Liste enthält eine Kennung doppelt."] = "The list contains an identifier twice.",
        ["Die Liste gehört zu einem anderen Land ({0})."] = "The list belongs to another country ({0}).",
        ["Die Liste ist keine gültige XML-Datei: {0}"] = "The list is not a valid XML file: {0}",
        ["Die Liste ist leer."] = "The list is empty.",
        ["Die Liste ist tiefer verschachtelt als {0} Ebenen."] = "The list is nested deeper than {0} levels.",
        ["Die Liste ist nicht von einer berechtigten Stelle signiert."] = "The list is not signed by an authorised body.",
        ["Die Liste ist veraltet — bitte neu laden."] = "The list is outdated — please load it again.",
        ["Die Liste ist zu groß."] = "The list is too large.",
        ["Die Liste trägt keine (oder mehr als eine) Signatur."] = "The list carries no (or more than one) signature.",
        ["Die Liste wurde nach dem Signieren verändert."] = "The list was changed after signing.",
        ["Die Signatur deckt nicht die ganze Liste ab."] = "The signature does not cover the whole list.",
        ["Die Signatur der Liste ist beschädigt."] = "The list's signature is damaged.",
        ["Die Signatur der Liste ist unvollständig ({0})."] = "The list's signature is incomplete ({0}).",
        ["Die Signatur der Liste verweist auf einen fehlenden Teil."] = "The list's signature refers to a missing part.",
        ["Die Signatur der Liste verwendet ein nicht unterstütztes Verfahren."] = "The list's signature uses an unsupported method.",
        ["Die XML-Datei ist zu tief verschachtelt."] = "The XML file is nested too deeply.",
        ["Die gespeicherte Liste löschen; die Prüfung zeigt dann wieder nur, was das Zertifikat über sich sagt."] = "Delete the stored list; the check then again shows only what the certificate says about itself.",
        ["EU-Vertrauensliste"] = "EU trusted list",
        ["EU-Vertrauensliste laden"] = "Load EU trusted list",
        ["EU-Vertrauensliste …"] = "EU trusted list …",
        ["Entfernt."] = "Removed.",
        ["Geladen und geprüft."] = "Loaded and checked.",
        ["Geladen und geprüft; einige Länder fehlen (siehe oben)."] = "Loaded and checked; some countries are missing (see above).",
        ["Geladen wird nur auf Klick, von den Adressen, die die EU-Kommission veröffentlicht (rund 30 MB). Jede Liste ist signiert und wird geprüft, bevor sie zählt; gespeichert wird sie auf diesem Rechner."] = "Loading happens only on a click, from the addresses the European Commission publishes (about 30 MB). Every list is signed and checked before it counts; it is stored on this computer.",
        ["Geprüft ohne Internet: Vertrauen über die Stammzertifikate dieses Systems und, wenn geladen, die EU-Vertrauensliste; Sperrstatus nur, was die Datei mitbringt. Ohne Zeitstempel hat der Unterzeichner die Zeit selbst angegeben."] = "Checked without internet: trust through the root certificates of this system and, if loaded, the EU trusted list; revocation status only what the file carries. Without a time stamp, the signer stated the time.",
        ["Lade und prüfe {0} …"] = "Loading and checking {0} …",
        ["Laden"] = "Load",
        ["Liste vom {0}, nächste Ausgabe spätestens {1}; {2} Länder geprüft."] = "List of {0}, next issue at the latest {1}; {2} countries checked.",
        ["Nicht erreichbar ({0})."] = "Not reachable ({0}).",
        ["Nicht geladen."] = "Not loaded.",
        ["Nicht geladen. Ohne die Liste zeigt die Prüfung nur, was das Zertifikat über sich selbst sagt."] = "Not loaded. Without the list, the check shows only what the certificate says about itself.",
        ["Nicht geladen: {0}"] = "Not loaded: {0}",
