        ["{0} ({1}) — zur Unterschriftszeit nicht als qualifiziert geführt"] = "{0} ({1}) — not listed as qualified at the time of signing",
        ["Der Server leitet woandershin um ({0})."] = "The server redirects elsewhere ({0}).",
        ["Das Zertifikat ist abgelaufen; der Zeitstempel stammt von einem Dienst, dem dieser Rechner nicht vertraut, und bestätigt deshalb nichts."] = "The certificate has expired; the time stamp comes from a service this computer does not trust and therefore confirms nothing.",
        ["Achtung: letzter Versuch, danach ist die Karte gesperrt."] = "Caution: last try, after that the card is locked.",
        ["Auf der Karte gibt es zu diesem Zertifikat keinen Schlüssel."] = "The card holds no key for this certificate.",
