        ["Beim Unterschreiben fragt PDF-Knead nach der PIN der Karte."] = "When signing, PDF-Knead asks for the card's PIN.",
        ["Beim Unterschreiben wird die PIN am Kartenleser eingegeben."] = "When signing, the PIN is entered at the card reader.",
        ["Bitte die PIN am Kartenleser eingeben …"] = "Please enter the PIN at the card reader …",
        ["Bitte zuerst einen Kartentreiber wählen."] = "Please choose a card driver first.",
        ["Den Treiber (PKCS#11-Bibliothek) Ihrer Karte wählen, wenn er nicht in der Liste steht. Nur Treiber aus vertrauenswürdiger Quelle wählen: PDF-Knead führt ihn aus."] = "Choose the driver (PKCS#11 library) of your card if it is not in the list. Only choose drivers from a trustworthy source: PDF-Knead runs it.",
        ["Der Kartentreiber antwortet nicht ({0})."] = "The card driver does not answer ({0}).",
        ["Der Kartentreiber lässt sich nicht laden: {0}"] = "The card driver cannot be loaded: {0}",
        ["Der Schlüssel bleibt auf der Karte."] = "The key stays on the card.",
        ["Die Art des Schlüssels auf der Karte wird nicht unterstützt."] = "The kind of key on the card is not supported.",
        ["Die Datei ist kein Kartentreiber (PKCS#11): {0}"] = "The file is not a card driver (PKCS#11): {0}",
        ["Die Karte liefert keine Signatur."] = "The card returns no signature.",
        ["Die Karte meldet einen Fehler bei {0} ({1})."] = "The card reports an error at {0} ({1}).",
        ["Die Karte mit dem gewählten Zertifikat ist nicht im Leser. Bitte einlegen oder unter „Zertifikat“ ein anderes wählen."] = "The card with the chosen certificate is not in the reader. Please insert it or choose another one under “Certificate”.",
        ["Die Karte mit diesem Zertifikat ist nicht im Leser."] = "The card with this certificate is not in the reader.",
