        ["Kartentreiber (PKCS#11)"] = "Card driver (PKCS#11)",
        ["Kein Kartentreiber gefunden. Debian/Ubuntu: sudo apt install opensc — Fedora: sudo dnf install opensc"] = "No card driver found. Debian/Ubuntu: sudo apt install opensc — Fedora: sudo dnf install opensc",
        ["Keine Karte im Leser."] = "No card in the reader.",
        ["Liest die Zertifikate auf der Karte; die PIN wird erst beim Unterschreiben gebraucht."] = "Reads the certificates on the card; the PIN is only needed when signing.",
        ["PIN der Karte „{0}“ — bis zum Beenden gemerkt"] = "PIN of the card “{0}” — kept until closing",
        ["Signaturkarte"] = "Signature card",
        ["Signaturkarte oder Token"] = "Signature card or token",
        ["Signaturkarten werden unter Windows über den Zertifikatsspeicher angesprochen."] = "Under Windows, signature cards are reached through the certificate store.",
        ["Treiber wählen …"] = "Choose driver …",
        ["Zertifikat auf einer Signaturkarte"] = "Certificate on a signature card",
        ["{0} — {1}, gültig bis {2}"] = "{0} — {1}, valid until {2}",
        ["Auf der Karte ist kein Zertifikat zu finden."] = "No certificate found on the card.",
        ["Der Kartentreiber lässt sich nicht starten ({0})."] = "The card driver cannot be started ({0}).",
        ["SoftHSM ist ein Testwerkzeug, keine Karte; es braucht Zugriff auf seinen Token-Ordner (Gruppe „softhsm“)."] = "SoftHSM is a test tool, not a card; it needs access to its token folder (group “softhsm”).",
        ["Kein Kartenleser gefunden. Ist er angeschlossen und läuft der Kartendienst? Debian/Ubuntu: sudo apt install pcscd — Fedora: sudo dnf install pcsc-lite"] = "No card reader found. Is it connected and is the card service running? Debian/Ubuntu: sudo apt install pcscd — Fedora: sudo dnf install pcsc-lite",
        ["{0} Dateien, {1} Seiten, {2} Stellen, {3} nicht lesbar, {4:0.0} s"] = "{0} files, {1} pages, {2} spots, {3} unreadable, {4:0.0} s",
