        ["Kartennummern"] = "Card numbers",
        ["Kontonummern im IBAN-Format; passt die Prüfziffer nicht, erscheint der Fund ohne Haken (vielleicht ein Tippfehler, vielleicht keine IBAN)."] = "Account numbers in IBAN format; if the check digits do not fit, the hit appears unticked (perhaps a typo, perhaps no IBAN).",
        ["Kredit- und Bankkartennummern (13 bis 19 Ziffern) mit gültiger Prüfziffer — andere lange Nummern werden nicht gemeldet."] = "Credit and bank card numbers (13 to 19 digits) with a valid check digit — other long numbers are not reported.",
        ["Liste laden …"] = "Load list …",
        ["Liste speichern …"] = "Save list …",
        ["Prüfziffer passt nicht"] = "check digits do not fit",
        ["Wortliste"] = "Word list",
        ["Wortliste gespeichert."] = "Word list saved.",
        ["Wortliste laden"] = "Load word list",
        ["Wortliste speichern"] = "Save word list",
        ["Wörter oder Namen aus einer Textdatei übernehmen (je Zeile einer) oder aus einer Tabelle, als CSV mit Semikolon gespeichert."] = "Take words or names from a text file (one per line) or from a table saved as CSV with semicolons.",
        ["Zum Beispiel 24.12.2026, 24/12/26, 2026-12-24, 24. Dezember 2026"] = "For example 24.12.2026, 24/12/26, 2026-12-24, 24 December 2026",
        // text recognition: models come with the program, small the default (decided on 13.11.2026)
        ["Die Modelle der Texterkennung fehlen im Ordner „ocr“ neben dem Programm — bitte PDF-Knead neu entpacken bzw. installieren."] = "The text recognition models are missing from the folder “ocr” next to the program — please unpack or install PDF-Knead again.",
        ["Die Modelle der Texterkennung fehlen im Ordner „ocr“ neben dem Programm."] = "The text recognition models are missing from the folder “ocr” next to the program.",
        ["Die Texterkennung ließ sich nicht starten — die Modelle im Ordner „ocr“ neben dem Programm fehlen oder sind beschädigt. Bitte PDF-Knead neu entpacken bzw. installieren."] = "The text recognition could not be started — the models in the folder “ocr” next to the program are missing or damaged. Please unpack or install PDF-Knead again.",
        ["Ein Modell im Ordner „ocr“ neben dem Programm fehlt oder ließ sich nicht öffnen — bitte PDF-Knead neu entpacken bzw. installieren."] = "A model in the folder “ocr” next to the program is missing or could not be opened — please unpack or install PDF-Knead again.",
        ["Paddle 6: medium — am genauesten, langsamer"] = "Paddle 6: medium — most exact, slower",
        ["Paddle 6: small — schnell (Vorgabe)"] = "Paddle 6: small — fast (default)",
        // persons, companies and addresses in „Suchen und schwärzen“ (KONZEPT.md, section 5.23)
        ["Personen"] = "Persons",
        ["Namen von Personen, erkannt an Anrede, Titel, Feldnamen und Namenslisten vieler Sprachen — ohne KI. Unsichere Funde erscheinen ohne Haken, mit dem Grund daneben."] = "Names of persons, recognised by form of address, title, field names and name lists of many languages — without AI. Uncertain hits appear unticked, with the reason beside them.",
        ["Firmen und Organisationen"] = "Companies and organisations",
        ["Namen vor einer Rechtsform (GmbH, AG, Ltd., S.r.l. …) und Einrichtungen mit einem Namen daneben (Sparkasse …, Amtsgericht …)."] = "Names before a legal form (GmbH, AG, Ltd., S.r.l. …) and institutions with a name beside them (Sparkasse …, Amtsgericht …).",
        ["Alle Teile einer Anschrift; jeder Teil wird ein eigener Fund mit eigenem Haken."] = "All parts of an address; each part becomes a hit of its own with its own tick.",
        ["Straße"] = "Street",
        ["Hausnummer"] = "House number",
        ["PLZ"] = "Postal code",
        ["Postleitzahlen in den Formaten vieler Länder — nur neben einem Ort oder nach einer Straße, sonst wäre jede Zahl eine."] = "Postal codes in the formats of many countries — only next to a place or after a street, otherwise every number would be one.",
        ["Der Ort einer Anschrift (nach der Postleitzahl, nach Straße und Komma) oder ein bekannter Ort nach „in“, „aus“ …"] = "The place of an address (after the postal code, after street and comma) or a known place after “in”, “from” …",
        ["Land"] = "Country",
        ["Postfach"] = "P.O. box",
        ["Orte (überall)"] = "Places (everywhere)",
        ["Bekannte Ortsnamen auch außerhalb von Anschriften."] = "Known place names also outside addresses.",
        ["Gründlich (unbekannte Namen vorschlagen)"] = "Thorough (suggest unknown names)",
        ["Zusätzlich jedes großgeschriebene Wort, das kein bekanntes Wort ist, als Vorschlag ohne Haken — findet auch Namen, die keine Liste kennt, bringt aber viele Vorschläge. Für heikle Dokumente."] = "In addition, every capitalised word that is no known word as an unticked suggestion — also finds names no list knows, but brings many suggestions. For sensitive documents.",
        ["Person"] = "Person",
        ["Name ist auch ein Wort"] = "name is also a word",
        ["nur ein einzelner Name aus der Liste"] = "only a single name from the list",
        ["Titel ist auch ein Wort"] = "title is also a word",
        ["unbekanntes Wort, vielleicht ein Name"] = "unknown word, perhaps a name",
        ["Nachschlagedatei: {0:N0} Bytes, gepackt {1:N0} Bytes"] = "Lexicon: {0:N0} bytes, packed {1:N0} bytes",
        ["Das Programm hat keine Nachschlagedatei."] = "The program has no lexicon.",
        ["Archiv-Zeitstempel fehlgeschlagen: {0}"] = "Archive time stamp failed: {0}",
        ["Archiv-Zeitstempel hinzufügen"] = "Add archive time stamp",
        ["Archiv-Zeitstempel hinzugefügt, aber ohne vollständige Langzeitprüfung: für {0} war kein Sperrstatus zu bekommen."] = "Archive time stamp added, but without complete long-term validation: no revocation status could be obtained for {0}.",
        ["Archiv-Zeitstempel hinzugefügt: {0}"] = "Archive time stamp added: {0}",
        ["Archiv-Zeitstempel verwenden"] = "Use archive time stamps",
        ["Archiv-Zeitstempel über das ganze Dokument anhängen (für sehr lange Aufbewahrung)"] = "Append an archive time stamp over the whole document (for very long retention)",
        ["Archiv-Zeitstempel …"] = "Archive time stamp …",
        ["Bitte das Dokument zuerst speichern."] = "Please save the document first.",
        ["Das Dokument hat keine digitale Signatur, die ein Archiv-Zeitstempel schützen könnte."] = "The document has no digital signature an archive time stamp could protect.",
        ["Das Prüfsummenverfahren des Dokument-Zeitstempels wird nicht geprüft."] = "The digest method of the document time stamp is not checked.",
        ["Der Dokument-Zeitstempel ist beschädigt."] = "The document time stamp is damaged.",
        ["Der Dokument-Zeitstempel passt nicht zum Inhalt: das Dokument wurde verändert."] = "The document time stamp does not match the content: the document was changed.",
        ["Der Dokument-Zeitstempel verwendet SHA-1; das gilt heute als veraltet."] = "The document time stamp uses SHA-1; that is considered outdated today.",
        ["Der Zeitstempel ist zu groß."] = "The time stamp is too large.",
        ["Dokument-Zeitstempel"] = "Document time stamp",
        ["Dokument-Zeitstempel von {0}"] = "Document time stamp by {0}",
        ["Für einen Archiv-Zeitstempel bitte unter „Zertifikat“ einen Zeitstempeldienst eintragen."] = "For an archive time stamp, please enter a time-stamping service under “Certificate”.",
        ["Hole Sperrstatus und Archiv-Zeitstempel …"] = "Fetching revocation status and archive time stamp …",
        ["Hängt den aktuellen Sperrstatus und einen Zeitstempel über das ganze Dokument an — so bleiben die Unterschriften auch nach Ablauf der Zertifikate prüfbar. Vor dem Ablauf des letzten Zeitstempels wiederholen. Die Unterschriften bleiben gültig."] = "Appends the current revocation status and a time stamp over the whole document — the signatures then stay checkable after the certificates expire. Repeat before the last time stamp expires. The signatures stay valid.",
        ["Kein Archiv-Zeitstempel: {0}"] = "No archive time stamp: {0}",
        ["Nach Unterschrift und Sperrstatus bestätigt der Zeitstempeldienst noch einmal das ganze Dokument. So bleibt die Unterschrift auch nach Ablauf aller Zertifikate prüfbar; unter „Dokument Signaturen“ lässt er sich vor seinem Ablauf erneuern. Braucht einen Zeitstempeldienst."] = "After signature and revocation status, the time-stamping service confirms the whole document once more. The signature then stays checkable after all certificates expire; under “Document signatures” it can be renewed before it expires. Needs a time-stamping service.",
        ["Der Zeitstempeldienst ist nicht erreichbar ({0})."] = "The time-stamping service cannot be reached ({0}).",
        ["Der Zeitstempeldienst ist nicht erreichbar."] = "The time-stamping service cannot be reached.",
        ["Die Adresse ist ungültig (beginnt mit http:// oder https://)."] = "The address is invalid (it starts with http:// or https://).",
        ["Die Antwort des Zeitstempeldienstes ist zu groß."] = "The answer of the time-stamping service is too large.",
        ["Dienst prüfen"] = "Check service",
        ["Dieser Rechner kennt ihn nicht als vertrauenswürdig — PDF-Leser zeigen die Zeit dann womöglich als unbestätigt."] = "This computer does not know it as trustworthy — PDF readers may then show the time as unconfirmed.",
        ["Dieser Rechner vertraut ihm."] = "This computer trusts it.",
        ["Ein Zeitstempeldienst bestätigt, wann unterschrieben wurde — dann bleibt die Unterschrift auch nach Ablauf des Zertifikats prüfbar. Gesendet wird nur eine Prüfsumme der Unterschrift, nichts vom Dokument."] = "A time-stamping service confirms when it was signed — then the signature can still be checked after the certificate has expired. Only a checksum of the signature is sent, nothing of the document.",
        ["Frage den Zeitstempeldienst …"] = "Asking the time-stamping service …",
        ["Kein Zeitstempel"] = "No time stamp",
        ["Ohne Zeitstempel ist die Unterschrift gültig, aber ihre Zeit bestätigt kein Dritter."] = "Without a time stamp the signature is valid, but no third party confirms its time.",
        ["Ohne Zeitstempel signieren"] = "Sign without time stamp",
        ["PDF-Knead verbindet sich nur mit dieser Adresse und nur beim Unterschreiben. Die bekannten Dienste sind frei und weltweit anerkannt, aber nicht qualifiziert; qualifizierte Zeitstempel (eIDAS) bieten Vertrauensdiensteanbieter gegen Gebühr und mit Anmeldung an."] = "PDF-Knead connects only to this address and only when signing. The known services are free and recognised worldwide, but not qualified; qualified time stamps (eIDAS) are offered by trust service providers for a fee and with a login.",
        ["Adresse übernommen. „Dienst prüfen“ zeigt, ob er antwortet."] = "Address taken. “Check service” shows whether it answers.",
        ["Bekannte Dienste …"] = "Known services …",
        ["Bekannte Zeitstempeldienste"] = "Known time-stamping services",
        ["Freie Zeitstempeldienste, denen die üblichen Systeme vertrauen. Nichts ist voreingestellt: erst die Wahl hier trägt die Adresse ein."] = "Free time-stamping services trusted by the common systems. Nothing is preset: only choosing here enters the address.",
        ["DigiCert (frei, ohne Anmeldung)"] = "DigiCert (free, no login)",
        ["Sectigo (frei, ohne Anmeldung)"] = "Sectigo (free, no login)",
        ["Schickt eine Probe-Anfrage (ein Zufallswert, nichts aus einem Dokument) und zeigt, wer antwortet."] = "Sends a test request (a random value, nothing from a document) and shows who answers.",
        ["Unterschriften mit einem Zeitstempel versehen (braucht eine Internetverbindung)"] = "Give signatures a time stamp (needs an internet connection)",
        ["Zeitstempel"] = "Time stamp",
        ["Zeitstempel verwenden"] = "Use time stamps",
        ["einem Zeitstempeldienst"] = "a time-stamping service",
        ["passt nicht zur Signatur"] = "does not match the signature",
        ["{0} — bestätigt von {1}"] = "{0} — confirmed by {1}",
        ["Bisheriges Passwort"] = "Current password",
        ["Das Passwort des Zertifikats stimmt nicht."] = "The password of the certificate is wrong.",
        ["Das Passwort des eigenen Zertifikats stimmt nicht. Vergessen? Unter „Zertifikat“ lässt sich ein neues erzeugen; schon gesetzte Unterschriften bleiben gültig."] = "The password of the own certificate is wrong. Forgotten? A new one can be created under “Certificate”; signatures already made stay valid.",
        ["Das Passwort ließ sich nicht speichern."] = "The password could not be saved.",
        ["Das Passwort ließ sich nicht speichern: {0}"] = "The password could not be saved: {0}",
        ["Das Passwort schützt den Schlüssel des eigenen Zertifikats auf diesem Rechner zusätzlich. Beim ersten Unterschreiben nach dem Start wird es abgefragt und bis zum Beenden gemerkt. Vergessen lässt es sich nicht wiederherstellen — dann ein neues Zertifikat erzeugen; schon gesetzte Unterschriften bleiben gültig."] = "The password additionally protects the key of the own certificate on this computer. It is asked the first time you sign after starting and kept until you quit. A forgotten password cannot be recovered — then create a new certificate; signatures already made stay valid.",
        ["Das Passwort stimmt nicht."] = "The password is wrong.",
        ["Das bisherige Passwort stimmt nicht."] = "The current password is wrong.",
        ["Das eigene Zertifikat ist mit einem Passwort geschützt."] = "The own certificate is protected by a password.",
        ["Das eigene Zertifikat lässt sich nicht lesen. Bitte unter „Zertifikat“ ein neues erzeugen."] = "The own certificate cannot be read. Please create a new one under “Certificate”.",
        ["Festlegen"] = "Set",
        ["Freiwillig: Ein Passwort schützt den Schlüssel des eigenen Zertifikats zusätzlich. Es wird beim ersten Unterschreiben nach dem Start abgefragt."] = "Optional: a password additionally protects the key of the own certificate. It is asked the first time you sign after starting.",
        ["Neues Passwort wiederholen"] = "Repeat the new password",
