        ["Code im Balken anzeigen"] = "Show the code in the bar",
        ["Beim Schwärzen steht der Code (oder der eigene Grund) klein im Balken; Bedeutung und Rechtsgrundlage stehen im Schwärzungsprotokoll"] =
            "When redacting, the code (or the own reason) is written small into the bar; its meaning and legal basis go into the redaction protocol",
        ["Code je Fundart automatisch setzen"] = "Set the code by kind of hit",
        ["E-Mail, Telefon, IBAN, Kartennummer und Datum bekommen den Code, den die Code-Datei des Landes für sie vorsieht; eigene Wörter den gewählten Code"] =
            "E-mail, phone, IBAN, card number and date get the code the country's code file names for them; own words get the chosen code",
        ["Passt nicht in den Balken — dort wird er weggelassen, im Schwärzungsprotokoll steht er."] =
            "Does not fit into the bar — it is left out there, the redaction protocol has it.",
        ["Passt in {0} von {1} Balken nicht — dort wird er weggelassen, im Schwärzungsprotokoll steht er."] =
            "Does not fit into {0} of {1} bars — it is left out there, the redaction protocol has it.",
        ["Schwärzungsgrund für die gewählten Funde (freiwillig)"] = "Reason for the chosen hits (optional)",
        ["Code oder Grund in die Balken schreiben (weiß, wo er hineinpasst)"] = "Write the code or reason into the bars (white, where it fits)",
        ["Bei Markierungen mit eigenem Grund so, wie bei der Markierung gewählt („Code im Balken anzeigen“); aus: in keinen Balken"] =
            "For marks with their own reason as chosen at the mark (“Show the code in the bar”); off: into no bar",
        ["1 davon mit Schwärzungscode."] = "1 of them with a redaction code.",
        ["{0} davon mit Schwärzungscode."] = "{0} of them with a redaction code.",
        ["SCHWÄRZUNGSCODES"] = "REDACTION CODES",
        ["Die Codes für die Gründe beim Schwärzen, je Land eine Textdatei mit einer Zeile je Code (Code, Kurztext, Bedeutung, Rechtsgrundlage, Fundarten — durch Tabulator getrennt, auch in einer Tabellenkalkulation zu bearbeiten). Eine eigene Fassung ersetzt die mitgelieferte."] =
            "The codes for the reasons when redacting, one text file per country with one line per code (code, short text, meaning, legal basis, kinds of hits — separated by tabs, also editable in a spreadsheet). An own version replaces the one supplied.",
        ["Bearbeiten …"] = "Edit …",
        ["Öffnet die Code-Datei im Texteditor; eine mitgelieferte wird dafür in den Ordner oben kopiert"] =
            "Opens the code file in the text editor; a supplied one is copied into the folder above for this",
        ["Code-Datei hinzufügen …"] = "Add code file …",
        ["Eigene Fassung beiseitelegen"] = "Put own version aside",
        ["Die eigene Datei wird in .bak umbenannt (nichts geht verloren); es gelten wieder die mitgelieferten Codes"] =
            "The own file is renamed to .bak (nothing is lost); the supplied codes apply again",
        ["Zum Bearbeiten: {0} — nach dem Speichern „Neu laden“."] = "To edit: {0} — after saving, “Reload”.",
        ["Die Code-Datei ließ sich nicht anlegen: {0}"] = "The code file could not be created: {0}",
        ["Die Datei ist größer als 1 MB."] = "The file is larger than 1 MB.",
        ["Sie enthält keinen Code."] = "It contains no code.",
