        ["Die Code-Datei ließ sich nicht speichern: {0}"] = "The code file could not be saved: {0}",
        ["Eigene Fassung beiseitegelegt ({0}) — es gelten wieder die mitgelieferten Codes für „{1}“."] =
            "Own version put aside ({0}) — the supplied codes for “{1}” apply again.",
        ["Die Code-Datei ließ sich nicht entfernen: {0}"] = "The code file could not be removed: {0}",
        ["Code-Datei hinzufügen"] = "Add code file",
        ["Code-Datei exportieren"] = "Export code file",
        ["Textdatei"] = "Text file",
        ["schon markiert"] = "already marked",
        ["1 davon schon markiert"] = "1 of them already marked",
        ["{0} davon schon markiert"] = "{0} of them already marked",
        ["Danach nur Prüfdaten für die Langzeitprüfung oder Dokument-Zeitstempel hinzugefügt."] = "Afterwards only validation data for long-term validation or document time stamps were added.",
        ["Danach wurden die Dokumenteigenschaften (Titel, Autor, Datum …) geändert."] = "Afterwards the document properties (title, author, date …) were changed.",
        ["Der Sicherheitsspeicher (/DSS) hat eine unbekannte Form."] = "The security store (/DSS) has an unknown shape.",
        ["Das Signaturverfahren {0} wird nicht geprüft."] = "The signature method {0} is not checked.",
        ["SHAKE256 mit variabler Länge"] = "SHAKE256 with variable length",
        ["Der Signaturblock nennt ein anderes Zertifikat als das, mit dem unterschrieben wurde: das Zertifikat wurde ausgetauscht."] = "The signature block names another certificate than the one it was signed with: the certificate was swapped.",
        ["Der Signaturblock ist nicht normgerecht (Angabe zum Zertifikat des Unterzeichners)."] = "The signature block does not conform to the standard (statement about the signer’s certificate).",
        ["Welches Zertifikat unterschrieben hat, lässt sich nicht prüfen (unbekanntes Prüfsummenverfahren der Angabe zum Zertifikat)."] = "Which certificate signed cannot be checked (unknown digest method of the statement about the certificate).",
        ["Der Signaturblock bindet das Zertifikat des Unterzeichners nicht (signing-certificate fehlt); bei PAdES ist das Pflicht."] = "The signature block does not bind the signer’s certificate (signing-certificate missing); PAdES requires it.",
        ["Das Signaturwörterbuch trägt ein Zertifikat (/Cert); bei PAdES ist das nicht vorgesehen."] = "The signature dictionary carries a certificate (/Cert); PAdES does not provide for that.",
        ["Die Unterschriftszeit steht in /M und im Signaturblock; bei PAdES ist nur eine der beiden vorgesehen."] = "The signing time is in /M and in the signature block; PAdES provides for only one of them.",
        ["Die Art des unterschriebenen Inhalts ist nicht „Daten“ (id-data); bei PAdES ist das vorgesehen."] = "The type of the signed content is not “data” (id-data); PAdES provides for that.",
        ["Der Signaturblock trägt ein Attribut, das PAdES ausschließt (Gegensignatur oder Inhaltsverweis)."] = "The signature block carries an attribute PAdES excludes (counter-signature or content reference).",
        ["Inhalt und signierte Attribute sind mit verschiedenen Prüfsummenverfahren gesichert; vorgesehen ist dasselbe."] = "Content and signed attributes are secured with different digest methods; the same one is intended.",
        ["Das Signaturfeld sieht eine Feldsperre vor, die die Signatur nicht enthält."] = "The signature field provides for a field lock the signature does not contain.",
