        ["Für Kommentare wurden Symbole hinterlegt."] = "Icons for comments were stored.",
        ["Die Angabe zum Zertifikat im Signaturblock nennt einen anderen Aussteller oder eine andere Seriennummer; die Prüfsumme bindet das Zertifikat trotzdem."] = "The certificate reference in the signature block names another issuer or serial number; its hash binds the certificate all the same.",
        ["Der Signaturblock ist nicht normgerecht (die Prüfsumme der unterschriebenen Daten fehlt)."] = "The signature block is not made to the standard (the digest of the signed data is missing).",
        ["Den signierten Attributen fehlt die Art des Inhalts (content-type); RFC 5652 verlangt sie."] = "The signed attributes lack the content type (content-type); RFC 5652 requires it.",
        ["Das Zertifikat nennt keine eindeutige Art (Signatur, Siegel oder Webseite)."] = "The certificate names no single kind (signature, seal or website).",
        ["Bei der Ausstellung des Zertifikats war der Anbieter laut EU-Vertrauensliste nicht qualifiziert."] = "When the certificate was issued, the provider was not qualified according to the EU trusted list.",
        ["Die EU-Vertrauensliste führt dieses Zertifikat als nicht qualifiziert."] = "The EU trusted list marks this certificate as not qualified.",
        ["Die EU-Vertrauensliste führt den Aussteller zur Unterschriftszeit nicht als qualifizierten Anbieter."] = "At signing time the EU trusted list does not list the issuer as a qualified provider.",
        ["Mehrere Einträge der EU-Vertrauensliste widersprechen sich für dieses Zertifikat."] = "Several entries of the EU trusted list contradict each other for this certificate.",
        ["Die geladene EU-Vertrauensliste ({0}, Nr. {1}) ist veraltet: die nächste Ausgabe war am {2} fällig. Laden Sie sie neu."] = "The loaded EU trusted list ({0}, no. {1}) is out of date: the next issue was due on {2}. Load it again.",
