        ["Strg+Klick folgt dem Link"] = "Ctrl+click follows the link",
        ["Diese Adresse öffnet PDF-Knead nicht: {0}"] = "PDF-Knead does not open this address: {0}",
        ["Die Adresse ist nicht als UTF-8 gespeichert."] = "The address is not stored as UTF-8.",
        ["Die Adresse ist relativ und zeigt auf eine Datei neben dem Dokument — so etwas öffnet PDF-Knead nicht."] = "The address is relative and points to a file beside the document — PDF-Knead does not open such a thing.",
        ["durch eine Sichtbarkeitsregel verborgene Inhalte"] = "content hidden by a visibility rule",
        ["Das Passwort enthält ein ungültiges Zeichen."] = "The password contains an invalid character.",
        ["Das Passwort enthält ein Steuerzeichen."] = "The password contains a control character.",
        ["Das Passwort enthält ein Zeichen aus einem privaten Bereich."] = "The password contains a private-use character.",
        ["Das Passwort enthält ein Nichtzeichen."] = "The password contains a noncharacter.",
        ["Das Passwort enthält ein Zeichen, das in Passwörtern nicht erlaubt ist (Steuerung der Darstellung oder Schreibrichtung)."] = "The password contains a character not allowed in passwords (controlling display or writing direction).",
        ["Das Passwort enthält ein nicht zugewiesenes Zeichen."] = "The password contains an unassigned character.",
        ["Verschlüsseltes Dokument in einer Hülle"] = "Encrypted document in a wrapper",
        ["„{0}“ ist eine Hülle: das eigentliche Dokument „{1}“ steckt verschlüsselt darin (Verfahren „{2}“). Soll es geöffnet werden?"] =
            "“{0}” is a wrapper: the actual document “{1}” is inside it, encrypted (method “{2}”). Open it?",
        ["Dokument öffnen"] = "Open document",
        ["Die geschützte Angabe der Verfahren im Signaturblock passt nicht zu den verwendeten: der Signaturblock ist verändert oder fehlerhaft."] =
            "The protected statement of the algorithms in the signature block does not match those used: the block was changed or is faulty.",
        ["Ein eigenständiger MAC nennt keine Signatur (/SigObjRef)."] = "A standalone MAC names no signature (/SigObjRef).",
        ["Ein MAC an einer Signatur hat im Integritätsschutz weder /ByteRange noch /MAC."] = "A MAC attached to a signature has neither /ByteRange nor /MAC in the integrity protection.",
        ["Der Integritätsschutz nennt nicht die Signatur, an der der MAC hängt (/SigObjRef)."] = "The integrity protection does not name the signature the MAC is attached to (/SigObjRef).",
        ["Die Byte-Bereiche der Signatur mit dem MAC sind ungültig."] = "The byte ranges of the signature carrying the MAC are invalid.",
        ["Zwischen den Byte-Bereichen der Signatur mit dem MAC steht mehr als ihr Signaturblock."] = "Between the byte ranges of the signature carrying the MAC there is more than its signature block.",
        ["Die Signatur mit dem MAC hat keinen Signaturblock."] = "The signature carrying the MAC has no signature block.",
        ["Der MAC passt nicht zu der Signatur, an der er hängt."] = "The MAC does not match the signature it is attached to.",
        ["Der Signaturblock mit dem MAC ist nicht lesbar."] = "The signature block carrying the MAC cannot be read.",
        ["Der Signaturblock mit dem MAC hat mehr als einen Unterzeichner."] = "The signature block carrying the MAC has more than one signer.",
        ["An der Signatur hängt kein MAC, obwohl der Integritätsschutz es sagt."] = "No MAC is attached to the signature, although the integrity protection says so.",
        ["An der Signatur hängt mehr als ein MAC."] = "More than one MAC is attached to the signature.",
        ["Im MAC an der Signatur fehlt die Prüfsumme der Signatur (signatureDigest)."] = "The MAC attached to the signature lacks the digest of the signature (signatureDigest).",
        ["Diese Datei ist zusätzlich gegen Veränderung geschützt (ISO/TS 32004), ihr fehlt aber, was ein neuer MAC braucht (Dateischlüssel, /KDFSalt); PDF-Knead kann sie so nicht fortschreiben."] = "This file is additionally protected against changes (ISO/TS 32004), but lacks what a new MAC needs (file key, /KDFSalt); PDF-Knead cannot update it like this.",
        ["Im Integritätsschutz fehlt der MAC-Wert (/MAC)."] = "The integrity protection lacks the MAC value (/MAC).",
        ["Der MAC-Wert (/MAC) steht nicht in der ausgesparten Lücke."] = "The MAC value (/MAC) does not stand in the gap left for it.",
        ["Die Verschlüsselung nennt Version 6 (AES-GCM) mit Revision {0} statt 7."] = "The encryption names version 6 (AES-GCM) with revision {0} instead of 7.",
        ["Der Kryptfilter der Anhänge (/EFF „{0}“) fehlt in der Verschlüsselung — die Anhänge werden wie die übrigen Datenströme gelesen."] =
            "The crypt filter of the attachments (/EFF “{0}”) is missing from the encryption — the attachments are read like the other streams.",
        ["Den Integritätsschutz kann PDF-Knead erst prüfen, wenn die Anhänge mit ihrem Passwort entsperrt sind."] =
            "PDF-Knead can check the integrity protection only once the attachments are unlocked with their password.",
        ["Das Passwort enthält eine Zeichenfolge, die nach älteren und neueren Unicode-Regeln verschieden normalisiert wird."] =
            "The password contains a sequence that older and newer Unicode rules normalise differently.",
        ["Das Passwort mischt Schreibrichtungen (zum Beispiel hebräische oder arabische mit lateinischen Buchstaben) — das ist in Passwörtern nicht erlaubt."] = "The password mixes writing directions (for example Hebrew or Arabic with Latin letters) — that is not allowed in passwords.",
        ["Integritätsschutz (MAC) verletzt: {0}"] = "Integrity protection (MAC) violated: {0}",
        ["Die Datei verlangt einen Integritätsschutz (MAC nach ISO/TS 32004), hat aber keinen — nicht normgerecht, die Unversehrtheit ist nicht nachweisbar."] = "The file asks for integrity protection (MAC per ISO/TS 32004) but has none — not conforming, its integrity cannot be shown.",
        ["Integrität (MAC)"] = "Integrity (MAC)",
