        ["nicht prüfbar — {0}"] = "not checkable — {0}",
        ["(die Datei öffnet ohne Passwort, der Schutz hält deshalb nichts ab)"] = "(the file opens without a password, so the protection keeps nothing out)",
        ["Die Querverweise der Datei mussten repariert werden; die neueste Fassung ist nicht sicher bestimmt."] = "The cross-references of the file had to be repaired; the newest revision is not certain.",
        ["Der Integritätsschutz (MAC) ist nicht lesbar."] = "The integrity protection (MAC) cannot be read.",
        ["Im Integritätsschutz fehlt die Angabe, wo der MAC steht."] = "The integrity protection does not say where the MAC is.",
        ["Unbekannte Lage des MAC („{0}“)."] = "Unknown location of the MAC (“{0}”).",
        ["Die Byte-Bereiche des Integritätsschutzes sind ungültig."] = "The byte ranges of the integrity protection are invalid.",
        ["Der Integritätsschutz deckt nicht die ganze Datei ab — sie wurde danach verändert, oder ein anderes Programm hat ihn beim Anhängen nicht erneuert."] = "The integrity protection does not cover the whole file — it was changed afterwards, or another program did not renew it when appending.",
        ["Der MAC-Wert steht nicht genau in der ausgesparten Lücke."] = "The MAC value does not fill exactly the gap left for it.",
        ["Der Schlüsselzusatz für den Integritätsschutz (/KDFSalt) fehlt oder hat nicht 32 Byte."] = "The salt for the integrity protection (/KDFSalt) is missing or not 32 bytes long.",
        ["Der Schlüssel des MAC passt nicht zur Datei."] = "The key of the MAC does not fit the file.",
        ["Der MAC stimmt nicht."] = "The MAC does not match.",
        ["Die Datei wurde nach dem Schützen verändert."] = "The file was changed after it was protected.",
        ["Nach dem MAC stehen weitere Daten."] = "There are further data after the MAC.",
        ["Der Integritätsschutz (MAC) entspricht nicht ISO/TS 32004."] = "The integrity protection (MAC) does not conform to ISO/TS 32004.",
        ["Der MAC nutzt eine andere Schlüsselableitung."] = "The MAC uses another key derivation.",
        ["Der MAC nutzt ein anderes Schlüssel-Verpackungsverfahren."] = "The MAC uses another key wrapping method.",
