        ["Der MAC nutzt ein unbekanntes Prüfsummenverfahren."] = "The MAC uses an unknown digest method.",
        ["Das Prüfsummenverfahren des MAC wird auf diesem System nicht unterstützt."] = "The digest method of the MAC is not supported on this system.",
        ["Die Angabe der Verfahren im MAC passt nicht zu den verwendeten."] = "The methods named in the MAC do not match those used.",
        ["Teile der Datei wurden nach dem Verschlüsseln verändert (Prüfsumme passt nicht) — sie bleiben leer."] = "Parts of the file were changed after encrypting (the checksum does not match) — they stay empty.",
        ["AES-GCM wird auf diesem System nicht unterstützt."] = "AES-GCM is not supported on this system.",
        ["Verschlüsselung Version 6 ohne AES-GCM-Filter (AESV4)."] = "Encryption version 6 without an AES-GCM filter (AESV4).",
        ["Die Datei war als PDF/A gekennzeichnet; mit {0} ist sie es nicht mehr. Die Kennung wurde entfernt. Für eine gültige PDF/A-Datei „Als PDF/A speichern“ wählen."] = "The file was identified as PDF/A; with {0} it no longer is. The identification was removed. For a valid PDF/A file choose “Save as PDF/A”.",
        ["Passwortschutz"] = "password protection",
        ["Brotli-Packverfahren"] = "Brotli packing",
