        ["Einzelheiten"] = "Details",
        ["Die Datei trägt qualifizierte Signaturen, der Dienst des Archiv-Zeitstempels ist laut EU-Vertrauensliste aber nicht qualifiziert; für den Beweiswert wäre ein qualifizierter Dienst besser."] = "The file carries qualified signatures, but according to the EU trusted list the service of the archive time stamp is not qualified; a qualified service would be better for the evidential value.",
        ["PAdES-Stufe"] = "PAdES level",
        ["Schutz erneuern bis spätestens"] = "Renew the protection by",
        ["jetzt (die Frist ist abgelaufen)"] = "now (the deadline has passed)",
        ["Kein Archiv-Zeitstempel: er belegt nur den heutigen Zustand, und die Datei enthält Signaturen, die nicht gültig sind ({0})."] = "No archive time stamp: it only proves the state of today, and the file contains signatures that are not valid ({0}).",
        ["Ein späterer Dokument-Zeitstempel belegt, dass die Signatur am {0} schon bestand; geprüft zu diesem Zeitpunkt."] = "A later document time stamp proves that the signature already existed on {0}; checked at that time.",
        ["Ein späterer Dokument-Zeitstempel belegt, dass dieser Zeitstempel am {0} schon bestand; geprüft zu diesem Zeitpunkt."] = "A later document time stamp proves that this time stamp already existed on {0}; checked at that time.",
        ["Die Unterschrift des Ausstellers auf dem Zertifikat „{0}“ ist ungültig."] = "The issuer's signature on the certificate “{0}” is invalid.",
        ["Das Zertifikat „{0}“ stellt Zertifikate aus, ist aber nicht als Zertifizierungsstelle ausgewiesen (basicConstraints fehlt)."] = "The certificate “{0}” issues certificates but is not marked as a certification authority (basicConstraints missing).",
        ["Das Zertifikat „{0}“ stellt Zertifikate aus, ist laut basicConstraints aber keine Zertifizierungsstelle."] = "The certificate “{0}” issues certificates but is no certification authority according to basicConstraints.",
        ["Das Zertifikat „{0}“ darf laut Schlüsselverwendung keine Zertifikate ausstellen."] = "According to its key usage, the certificate “{0}” may not issue certificates.",
        ["Die Kette ist länger, als das Zertifikat „{0}“ erlaubt (pathLenConstraint)."] = "The chain is longer than the certificate “{0}” allows (pathLenConstraint).",
        ["Das Zertifikat „{0}“ trägt eine als kritisch markierte Erweiterung, die die Prüfung nicht kennt."] = "The certificate “{0}” carries an extension marked critical that the check does not know.",
        ["Das Zertifikat „{0}“ verletzt die Namensbeschränkung eines Ausstellers."] = "The certificate “{0}” violates the name constraint of an issuer.",
        ["Die Kette des Zertifikats „{0}“ ist ungültig ({1})."] = "The chain of the certificate “{0}” is invalid ({1}).",
        ["Das Zertifikat „{0}“ ist auf diesem Rechner ausdrücklich als nicht vertrauenswürdig gesperrt."] = "The certificate “{0}” is explicitly blocked as untrusted on this computer.",
        ["Das Zertifikat „{0}“ der Kette war am {1} nicht gültig (gültig vom {2} bis {3})."] = "The certificate “{0}” of the chain was not valid on {1} (valid from {2} to {3}).",
        ["PDF {0}"] = "PDF {0}",
