        ["OpenType-Schriften"] = "OpenType fonts",
        ["16-Bit-Bilder"] = "16-bit images",
        ["Die XMP-Metadaten sind nicht lesbar; das Änderungsdatum darin wurde nicht nachgeführt."] = "The XMP metadata cannot be read; the modification date in it was not updated.",
        ["Ein Datenstrom nennt einen Kryptfilter, den die Verschlüsselung nicht kennt („{0}“)."] = "A stream names a crypt filter the encryption does not know (“{0}”).",
        ["Die Daten sind mit einem auf 16 Byte aufgefüllten Schlüssel verschlüsselt (nicht nach ISO 32000-2, 7.6.3.3) — so gelesen; eine Kopie wird nach der Norm verschlüsselt."] =
            "The data are encrypted with a key padded to 16 bytes (not as ISO 32000-2, 7.6.3.3 describes) — read that way; a copy is encrypted as the standard asks.",
        ["Metadaten einer Seite oder eines Bildes sind unverschlüsselt gespeichert, obwohl nur die des Dokuments es sein dürfen — so gelesen, wie sie dastehen."] = "Metadata of a page or an image are stored unencrypted, although only those of the document may be — read as they are stored.",
        ["Seite {0} ließ sich nicht prüfen"] = "page {0} could not be checked",
        ["{0} Seiten ließen sich nicht prüfen ({1})"] = "{0} pages could not be checked ({1})",
        ["Seite {0} nicht vollständig geprüft"] = "page {0} not checked completely",
        ["{0} Seiten nicht vollständig geprüft ({1})"] = "{0} pages not checked completely ({1})",
        ["Auf Seite {0} lag unter der Markierung kein verborgener Text mehr — dort wurde nichts entfernt."] = "On page {0} there was no hidden text left under the mark — nothing was removed there.",
        ["Auf {0} Seiten ({1}) lag unter den Markierungen kein verborgener Text mehr — dort wurde nichts entfernt."] = "On {0} pages ({1}) there was no hidden text left under the marks — nothing was removed there.",
        ["{0} Blöcke gewählt — Enter oder ein Klick auf einen von ihnen bearbeitet sie als einen, Esc hebt die Wahl auf."] = "{0} blocks chosen — Enter or a click on one of them edits them as one, Esc drops the choice.",
        ["Blöcke mit verschiedener Schreibrichtung lassen sich nicht zusammenfassen."] = "Blocks with different writing directions cannot be joined.",
        ["Auf Seite {0} war in einer Zeile zu wenig Platz: dort lässt der Balken die Länge des geschwärzten Worts noch ungefähr erkennen."] = "On page {0} a line had too little room: there the bar still roughly shows the length of the redacted word.",
        ["Auf {0} Seiten ({1}) war in einer Zeile zu wenig Platz: dort lässt der Balken die Länge des geschwärzten Worts noch ungefähr erkennen."] = "On {0} pages ({1}) a line had too little room: there the bar still roughly shows the length of the redacted word.",
        ["Länge geschwärzter Wörter verbergen"] = "Hide the length of redacted words",
        ["Verdeckte Teile von 1 Bild (ein Rahmen oder der Seitenrand schneidet es ab) — auf den sichtbaren Teil zuschneiden"] = "Hidden parts of 1 image (a frame or the edge of the page cuts it off) — crop to the visible part",
        ["Verdeckte Teile von {0} Bildern (ein Rahmen oder der Seitenrand schneidet sie ab) — auf den sichtbaren Teil zuschneiden"] = "Hidden parts of {0} images (a frame or the edge of the page cuts them off) — crop to the visible part",
        ["auf 1 Seite"] = "on 1 page",
        ["Auf Seite {0} steht Text, der sich nicht lesen lässt — die Suche findet ihn nicht. Dort bitte mit „Bereich schwärzen“ schwärzen."] = "Page {0} has text that cannot be read — the search does not find it. Please redact it there with “Redact area”.",
        ["Auf den Seiten {0} steht Text, der sich nicht lesen lässt — die Suche findet ihn nicht. Dort bitte mit „Bereich schwärzen“ schwärzen."] = "Pages {0} have text that cannot be read — the search does not find it. Please redact it there with “Redact area”.",
        ["auf {0} Seiten"] = "on {0} pages",
        ["(Die Seite sieht danach gleich aus. JPEG-Bilder werden dabei neu gespeichert.)"] = "(The page looks the same afterwards. JPEG images are saved anew.)",
        ["Auf Seite {0} ließ sich ein Bild nicht zuschneiden (Schablone, zu groß oder nicht lesbar) — sein verdeckter Teil ist noch in der Datei."] = "On page {0} an image could not be cropped (stencil, too large or unreadable) — its hidden part is still in the file.",
        ["Auf {0} Seiten ({1}) ließen sich Bilder nicht zuschneiden (Schablone, zu groß oder nicht lesbar) — ihre verdeckten Teile sind noch in der Datei."] = "On {0} pages ({1}) images could not be cropped (stencil, too large or unreadable) — their hidden parts are still in the file.",
        ["Wer jede Längenangabe ausschließen will: auch die Nachbarwörter schwärzen oder die Seiten als Bild flachlegen."] = "To rule out any hint of length: redact the neighbouring words as well, or flatten the pages as images.",
        ["Balken in Textzeilen werden auf feste Stufen verlängert, damit man an ihrer Breite nicht erraten kann, welches Wort darunter stand. Die Wörter danach rücken dafür etwas zusammen; keines wird verdeckt."] = "Bars in lines of text are lengthened to fixed steps, so that their width does not give away which word was underneath. The words after them move a little closer together for this; none is covered.",
        ["unsichtbarer Text, etwa OCR"] = "invisible text, such as OCR",
        ["auf einer ausgeblendeten Ebene"] = "on a hidden layer",
        ["außerhalb der Seite"] = "beside the page",
        ["weggeschnitten"] = "clipped away",
        ["winzige Schrift"] = "tiny type",
        ["weiß auf weiß oder verdeckt"] = "white on white or covered",
        ["Der verborgene Inhalt ließ sich auf Seite {0} nicht vollständig entfernen — es wurde nichts gespeichert."] =
            "The hidden content on page {0} could not be removed completely — nothing was saved.",
        ["Geschwärzt. Strg+Z nimmt es zurück — endgültig gelöscht wird der Inhalt erst beim Speichern."] = "Redacted. Ctrl+Z undoes it — the content is only deleted for good when you save.",
        ["Geschwärztes endgültig löschen?"] = "Delete redacted content for good?",
        ["Die geschwärzten Inhalte werden in „{0}“ endgültig gelöscht."] = "The redacted content will be deleted from “{0}” for good.",
        ["Wer das Original behalten möchte, speichert als neue Datei."] = "To keep the original, save as a new file.",
        // Certificate for digital signatures
        ["Aus dem Zertifikatsspeicher von Windows"] = "From the Windows certificate store",
