        ["Fingerabdruck in die Zwischenablage, etwa um ihn weiterzugeben"] = "Copy the fingerprint to the clipboard, for example to pass it on",
        ["Für das Zertifikat fehlt der Name."] = "The certificate needs a name.",
        ["Gültig bis {0}"] = "Valid until {0}",
        ["In der Datei ist kein Zertifikat mit privatem Schlüssel."] = "The file contains no certificate with a private key.",
        ["Mit welchem Zertifikat digitale Unterschriften signiert werden: eigenes, aus einer Datei oder (unter Windows) aus dem Zertifikatsspeicher. Zeigt auch den Fingerabdruck zum Weitergeben."] = "Which certificate signs digital signatures: your own, one from a file or (on Windows) one from the certificate store. Also shows the fingerprint to pass on.",
        ["Name für das eigene Zertifikat"] = "Name for the own certificate",
        ["Name, wie er in der Unterschrift stehen soll"] = "Name as it is to appear in the signature",
        ["Noch kein Zertifikat"] = "No certificate yet",
        ["Passwort der Zertifikatsdatei"] = "Password of the certificate file",
        ["Schließen"] = "Close",
        ["Selbst ausgestellt: PDF-Leser zeigen „Dokument unverändert“, aber „Identität nicht bestätigt“, weil niemand Unabhängiges den Namen geprüft hat. Wer den Fingerabdruck von Ihnen kennt, kann ihn vergleichen."] = "Self-issued: PDF readers show “document unchanged” but “identity not confirmed”, because no independent party checked the name. Anyone who has your fingerprint can compare it.",
        ["Von einer Zertifizierungsstelle ausgestellt: PDF-Leser, die ihr vertrauen, zeigen die Identität als bestätigt."] = "Issued by a certification authority: PDF readers that trust it show the identity as confirmed.",
        ["Wird beim ersten Signieren erzeugt"] = "Created when signing for the first time",
        ["Zertifikat"] = "Certificate",
        ["Speichert das eigene Zertifikat als Datei mit Passwort — zum Sichern oder um auf einem anderen Rechner damit zu unterschreiben."] =
            "Saves the own certificate as a file with a password — as a backup or to sign with it on another computer.",
