        ["Passwort für die exportierte Datei"] = "Password for the exported file",
        ["Passwort wiederholen"] = "Repeat password",
        ["Das Passwort braucht mindestens {0} Zeichen."] = "The password needs at least {0} characters.",
        ["Das Passwort ist zu kurz."] = "The password is too short.",
        ["Die beiden Passwörter stimmen nicht überein."] = "The two passwords do not match.",
        ["Zertifikat exportieren"] = "Export certificate",
        ["Zertifikat exportiert: {0}"] = "Certificate exported: {0}",
        ["Das Zertifikat ließ sich nicht exportieren: {0}"] = "The certificate could not be exported: {0}",
        ["Zertifikat aus der Datei übernommen."] = "Certificate from the file adopted.",
        ["Zertifikat aus einer Datei (.pfx, .p12)"] = "Certificate from a file (.pfx, .p12)",
        ["Zertifikat für digitale Unterschriften"] = "Certificate for digital signatures",
        ["Zertifikat mit Schlüssel"] = "Certificate with key",
        ["Zertifikatsdatei"] = "Certificate file",
        ["Zertifikatsspeicher von Windows"] = "Windows certificate store",
        ["Zertifizieren kann nur die erste Unterschrift eines Dokuments, und nur eine."] = "Only the first signature of a document can certify it, and only one.",
        ["Eine Unterschrift zertifiziert mit „keine Änderungen“ — weitere Unterschriften sind dann nicht möglich. Bitte eine andere Stufe wählen oder die übrigen Unterschriften entfernen."] = "A signature certifies with “no changes” — further signatures are then not possible. Please choose another level or remove the other signatures.",
        ["Die Zertifikatsdatei lässt sich nicht öffnen: falsches Passwort, oder die Datei ist beschädigt."] = "The certificate file cannot be opened: wrong password, or the file is damaged.",
        ["Das Feld „{0}“ zeigt danach etwas, das schon vorher in der Datei lag."] = "Afterwards the field “{0}” shows something that was already in the file before.",
        ["Die Signatur verwendet ein unsicheres Verfahren (MD5); sie schützt das Dokument nicht."] = "The signature uses an insecure method (MD5); it does not protect the document.",
        ["Die Signatur verwendet SHA-1; das gilt heute als veraltet."] = "The signature uses SHA-1, which is considered outdated today.",
        ["Der Schlüssel des Zertifikats ist zu kurz ({0} Bit); die Signatur schützt das Dokument nicht."] = "The certificate's key is too short ({0} bits); the signature does not protect the document.",
        ["Der Schlüssel des Zertifikats ist nach heutigem Stand zu kurz ({0} Bit)."] = "By today's standards the certificate's key is too short ({0} bits).",
        ["Der Signaturblock widerspricht sich (Art des unterschriebenen Inhalts)."] = "The signature block contradicts itself (type of the signed content).",
        ["Das Zertifikat ist abgelaufen; ohne Zeitstempel bestätigt nichts, dass vorher unterschrieben wurde."] = "The certificate has expired; without a time stamp nothing confirms that it was signed before.",
        ["Die angegebene Unterschriftszeit liegt in der Zukunft."] = "The stated signing time lies in the future.",
        ["Zur angegebenen Unterschriftszeit war das Zertifikat nicht gültig."] = "The certificate was not valid at the stated signing time.",
        ["Das Zertifikat gehört einer Zertifizierungsstelle und ist nicht zum Unterschreiben bestimmt."] = "The certificate belongs to a certification authority and is not meant for signing.",
        ["Das Zertifikat ist nicht zum Unterschreiben bestimmt (Schlüsselverwendung)."] = "The certificate is not meant for signing (key usage).",
        ["Das Zertifikat ist für einen anderen Zweck ausgestellt (zum Beispiel für eine Webseite), nicht zum Unterschreiben."] = "The certificate was issued for another purpose (for example a website), not for signing.",
        ["Das Zertifikat ist erst ab {0} gültig."] = "The certificate is valid only from {0}.",
        ["Das Zertifikat ist am {0} abgelaufen."] = "The certificate expired on {0}.",
        ["Mit diesem Zertifikat lässt sich nicht unterschreiben: {0}"] = "This certificate cannot sign: {0}",
        ["Die Prüfsumme passt nicht zum Verfahren des Schlüssels."] = "The digest does not fit the method of the key.",
        ["RSASSA-PSS mit diesen Parametern"] = "RSASSA-PSS with these parameters",
        ["Die Rechte dieser Datei sind nicht versiegelt (/Perms fehlt oder passt nicht) — sie könnten nachträglich verändert sein."] = "The permissions of this file are not sealed (/Perms missing or not matching) — they may have been changed afterwards.",
        ["Die offenen Rechte (/P) weichen von den versiegelten ab; es gelten die versiegelten. Die Datei verstößt damit gegen ISO 32000-2."] = "The open permissions (/P) differ from the sealed ones; the sealed ones apply. The file thereby violates ISO 32000-2.",
        ["Ein Kryptfilter der Datei verschlüsselt nicht (None)."] = "A crypt filter of the file does not encrypt (None).",
        ["Ob die Metadaten verschlüsselt sind, steht versiegelt anders als offen in der Datei; es gilt der versiegelte Wert."] = "Whether the metadata are encrypted is sealed differently from what the file states openly; the sealed value applies.",
        ["Verschlüsselungsangaben unvollständig — Verfahren angenommen."] = "Encryption data incomplete — method assumed.",
        ["Verschlüsselungsverfahren „{0}“ passt nicht zu Version {1}."] = "Encryption method “{0}” does not fit version {1}.",
        ["Verschlüsselungsverfahren „{0}“ wird nicht unterstützt."] = "Encryption method “{0}” is not supported.",
        ["Die Rechte dieser Datei erlauben kein Unterschreiben."] = "The permissions of this file do not allow signing.",
        ["Diese Datei ist zusätzlich gegen Veränderung geschützt (ISO/TS 32004); PDF-Knead kann sie noch nicht signieren."] = "This file is also protected against changes (ISO/TS 32004); PDF-Knead cannot sign it yet.",
        ["Mit RC4 verschlüsselte Dateien lassen sich nicht signieren. Bitte zuerst mit neuem Schutz (AES) speichern."] = "Files encrypted with RC4 cannot be signed. Please save them with new protection (AES) first.",
        ["Diese Anmerkung ist vom Ersteller gesperrt. Trotzdem ändern?"] = "Its author locked this annotation. Change it anyway?",
