        ["Trotzdem ändern"] = "Change anyway",
        ["Der Zeitstempeldienst signiert mit einem veralteten Verfahren (SHA-1 oder MD5); sein Zeitstempel würde die Zeit nicht sicher bestätigen."] = "The time-stamping service signs with an outdated method (SHA-1 or MD5); its time stamp would not confirm the time securely.",
        ["Der Zeitstempeldienst hat sein Zertifikat nicht mitgeschickt."] = "The time-stamping service did not send its certificate.",
        ["Das Zertifikat des Zeitstempeldienstes war zur Zeit des Zeitstempels nicht gültig."] = "The certificate of the time-stamping service was not valid at the time of the time stamp.",
        ["Das Zertifikat des Zeitstempeldienstes ist nicht für Zeitstempel bestimmt."] = "The certificate of the time-stamping service is not meant for time stamps.",
        ["Zertifikat nicht verwendbar"] = "Certificate not usable",
        ["Der Archiv-Zeitstempel braucht die Langzeitprüfung (Sperrstatus in der Datei); sie ist deshalb mit eingeschaltet."] = "The archive time stamp needs long-term validation (revocation status in the file); it is therefore switched on too.",
        ["Ausfüllen, Unterschreiben und Kommentare"] = "filling in, signing and comments",
        ["Ausfüllen, Unterschriften und Kommentare (nicht zertifizieren)"] = "Filling in, signatures and comments (do not certify)",
        ["Danach erlaubt:"] = "Allowed afterwards:",
        ["Das Dokument ist zertifiziert: danach sind keine Änderungen erlaubt."] = "The document is certified: no changes are allowed afterwards.",
        ["Das Dokument ist zertifiziert: danach sind nur Ausfüllen und Unterschreiben erlaubt, keine Kommentare."] = "The document is certified: only filling in and signing are allowed afterwards, no comments.",
        ["Das Feld „{0}“ ist durch diese Signatur gesperrt und wurde danach geändert."] = "The field “{0}” is locked by this signature and was changed afterwards.",
        ["Das Feld „{0}“ ist durch eine Signatur gesperrt."] = "The field “{0}” is locked by a signature.",
        ["Felder sperren"] = "Lock fields",
        ["Sperrt"] = "Locks",
        ["Was nach dem Signieren erlaubt ist"] = "What is allowed after signing",
        ["Wird danach ein Feld des Formulars geändert, zeigen PDF-Leser diese Unterschrift als ungültig an."] = "If a field of the form is changed afterwards, PDF readers show this signature as invalid.",
        ["Zertifizieren legt fest, was nach dieser Unterschrift noch erlaubt ist; alles andere zeigen PDF-Leser als Änderung an. Nur die erste Unterschrift eines Dokuments kann zertifizieren."] = "Certifying sets what is still allowed after this signature; PDF readers show anything else as a change. Only the first signature of a document can certify.",
        ["Zertifizieren: Ausfüllen, Unterschreiben und Kommentare"] = "Certify: filling in, signing and comments",
