        ["Auf Seite {0} wurde ein Formularfeld hinzugefügt."] = "A form field was added on page {0}.",
        ["Die Änderungen lassen sich nicht an die signierte Datei anhängen. Bitte als neue Datei speichern."] = "The changes cannot be appended to the signed file. Please save as a new file.",
        ["Grund: {0}"] = "Reason: {0}",
        ["Tipp: Abbrechen und die Unterschrift mit „Digital signieren“ einsetzen — dann bleibt die vorhandene Unterschrift gültig."] = "Tip: cancel and insert the signature with “Sign digitally” — then the existing signature stays valid.",
        ["Dann wird das Zertifikat beim ersten digitalen Signieren angelegt."] = "Then the certificate is created at the first digital signature.",
