        ["Das Verfahren {0} wird nicht geprüft."] = "The method {0} is not checked.",
        ["Das Zertifikat stammt von einer Stelle, der dieses System vertraut."] = "The certificate comes from an authority this system trusts.",
        ["Der Inhalt von Seite {0} wurde geändert."] = "The content of page {0} was changed.",
