        ["Die Nummern unter den Kacheln sind die bisherigen Seitenzahlen. „Übernehmen“ stellt die Seitenleiste um — Strg+Z nimmt es zurück, gespeichert wird wie gewohnt."] =
            "The numbers below the tiles are the previous page numbers. “Apply” rearranges the page list — Ctrl+Z undoes it, save as usual.",
        ["Seiten neu sortiert — Strg+Z nimmt es zurück."] = "Pages sorted — Ctrl+Z undoes it.",
        // Exporting
        ["Als PDF aus Bildern (sicher), als PDF/A fürs Archiv oder als Bilddateien je Seite — die geöffnete Datei bleibt, wie sie ist"] =
            "As a PDF made of images (secure), as PDF/A for archiving or as image files per page — the open file stays as it is",
        ["PDF — NORMAL"] = "PDF — NORMAL",
        ["Text bleibt kopierbar und durchsuchbar, Lesezeichen, Formularfelder und Kommentare bleiben. Das ist „Speichern unter“ mit Wahl der PDF-Version."] =
            "Text stays copyable and searchable; bookmarks, form fields and comments are kept. This is “Save as” with a choice of PDF version.",
        ["Zu „Speichern unter“"] = "Go to “Save as”",
        ["PDF ALS BILD — SICHER"] = "PDF AS IMAGES — SECURE",
        ["Eine neue PDF, jede Seite ein Bild: kein kopierbarer Text, keine verborgenen Daten. Markierte Schwärzungen werden dabei angewendet. Die geöffnete Datei bleibt, wie sie ist."] =
            "A new PDF with every page as an image: no copyable text, no hidden data. Marked redactions are applied. The open file stays as it is.",
        ["PDF als Bild exportieren"] = "Export PDF as images",
        ["PDF als Bild exportieren …"] = "Export PDF as images …",
        ["SEITEN ALS BILDER"] = "PAGES AS IMAGES",
        ["Alle oder die in der Seitenleiste gewählten Seiten als PNG, JPEG, TIFF (auch mehrseitig) oder WebP in einem Ordner, etwa für Präsentationen, Webseiten oder ein Archiv."] =
            "All pages or those selected in the page panel as PNG, JPEG, TIFF (also multi-page) or WebP in a folder, for example for presentations, websites or an archive.",
        ["Seiten als Bilder exportieren …"] = "Export pages as images …",
        ["Eine neue PDF, jede Seite ein Bild — so, wie sie angezeigt wird. Die geöffnete Datei bleibt, wie sie ist."] =
            "A new PDF with every page as an image — just as it is shown. The open file stays as it is.",
        ["Als Bild speichern"] = "Save as images",
        ["Jede Seite als Bilddatei in einen Ordner — Dateinamen wie „Name_001“."] = "Every page as an image file in a folder — file names like “Name_001”.",
        ["PNG — verlustfrei"] = "PNG — lossless",
        ["Gestochen scharf, größere Dateien; Schwarzweiß-Seiten mit einem Bit je Bildpunkt"] = "Crisp, larger files; black-and-white pages with one bit per pixel",
        ["JPEG — kleine Dateien"] = "JPEG — small files",
        ["Gut für Fotos und Farbscans; jedes Programm kann es öffnen"] = "Good for photos and colour scans; every program can open it",
        ["TIFF — verlustfrei, auch mehrseitig"] = "TIFF — lossless, also multi-page",
        ["Üblich zum Archivieren; Schwarzweiß-Seiten sehr klein mit dem Fax-Verfahren CCITT G4"] =
            "Common for archiving; black-and-white pages very small with the fax method CCITT G4",
        ["Alle Seiten in eine Datei"] = "All pages in one file",
        ["Eine mehrseitige TIFF-Datei statt einer Datei je Seite"] = "One multi-page TIFF file instead of one file per page",
        ["WebP — noch kleiner"] = "WebP — even smaller",
        ["Kleiner als JPEG bei gleichem Aussehen; ältere Programme öffnen es nicht, und die Auflösung wird nicht gespeichert"] =
            "Smaller than JPEG at the same look; older programs cannot open it, and the resolution is not stored",
        ["Höher: schärfer und größer; 85 bis 92 sieht man kaum vom Original"] = "Higher: sharper and larger; 85 to 92 hardly differs from the original",
