        ["Ganz eingebettete TrueType-Schriften behalten nur die Zeichen, die das Dokument zeigt — Schriften von Formularfeldern bleiben ganz"] = "Fully embedded TrueType fonts keep only the characters the document shows — fonts of form fields stay complete",
        ["Ganze Seite (0 oder Doppelklick)"] = "Whole page (0 or double-click)",
        ["Immer dabei und verlustfrei: Doppeltes zusammenlegen, Vorschaubilder und Daten anderer Programme entfernen, stärkste Packstufe, Objekt-Streams."] = "Always included and lossless: merge duplicates, remove thumbnails and data of other programs, strongest packing level, object streams.",
        ["JPEG-Qualität"] = "JPEG quality",
        ["KOMPRIMIERUNG"] = "COMPRESSION",
        ["Komprimieren – {0}"] = "Compress – {0}",
        ["Komprimiert gespeichert: {0} ({1})"] = "Saved compressed: {0} ({1})",
        ["Komprimiert speichern"] = "Save compressed",
        ["Komprimierung"] = "Compression",
        ["„Flachlegen als Bild“ ist vorgemerkt: Die Kopie besteht aus Seitenbildern, ohne Text."] = "“Flatten as image” is pending: the copy consists of page images, without text.",
        ["Linie ziehen: links vorher, rechts nachher. Mausrad zoomt, Ziehen verschiebt."] = "Drag the line: before on the left, after on the right. Mouse wheel zooms, dragging pans.",
        ["Mehr Einstellungen mit Vorher/Nachher …"] = "More settings with before/after …",
        ["Nachher"] = "After",
        ["Nicht komprimieren"] = "Do not compress",
        ["Nur verlustfrei — Aussehen bleibt gleich"] = "Lossless only — appearance stays the same",
        ["Nächste Seite (Bild ab)"] = "Next page (Page Down)",
        ["Nächste Seite"] = "Next page",
        ["SCHRIFTEN UND PACKEN"] = "FONTS AND PACKING",
        ["Schriften auf benutzte Zeichen kürzen"] = "Subset fonts to the characters used",
