        // Removing restrictions (see KONZEPT.md, section 5.11)
        ["Einschränkungen entfernen"] = "Remove restrictions",
        ["Drucken, Kopieren, Ändern … wieder erlauben — mit dem Rechte-Passwort oder nach der Bestätigung, dazu berechtigt zu sein; ein Passwort zum Öffnen bleibt nötig"] =
            "Allow printing, copying, changing … again — with the permissions password or after confirming you are entitled to; an open password is still needed",
        ["Die Rechte dieser Datei lassen sich nicht ändern."] = "The permissions of this file cannot be changed.",
        ["Drucken in hoher Auflösung"] = "Printing in high resolution",
        ["Ändern"] = "Changing",
        ["Die Einschränkungen sind aufgehoben; in der Datei ab dem nächsten Speichern. Das Passwort zum Öffnen bleibt."] =
            "The restrictions are lifted; in the file from the next save. The open password stays.",
        ["Die Einschränkungen sind aufgehoben; in der Datei ab dem nächsten Speichern."] = "The restrictions are lifted; in the file from the next save.",
        ["Die Datei sperrt: {0}."] = "The file locks: {0}.",
        ["Die Datei sperrt nichts, sie hat nur ein Passwort für die Rechte."] = "The file locks nothing, it only has a permissions password.",
        ["Rechte-Passwort, falls bekannt"] = "Permissions password, if known",
        ["Das Rechte-Passwort stimmt."] = "The permissions password is correct.",
        ["Das ist nicht das Rechte-Passwort."] = "That is not the permissions password.",
        ["Es ist meine Datei, oder ich habe die Zustimmung des Eigentümers, die Einschränkungen ohne das Rechte-Passwort zu entfernen."] =
            "It is my file, or I have the owner's consent to remove the restrictions without the permissions password.",
        ["Ohne das Rechte-Passwort ist das Entfernen durch die Funktionsdatei Ihrer Organisation gesperrt."] =
            "Removing without the permissions password is blocked by the function file of your organization.",
        ["Einschränkungen ohne Passwort entfernen"] = "Remove restrictions without a password",
        ["Damit werden die Rechte der Datei (z. B. Drucken, Kopieren, Ändern) aufgehoben, ohne dass Sie das Rechte-Passwort kennen. Das ist nur erlaubt, wenn es Ihre eigene Datei ist oder der Eigentümer bzw. Rechteinhaber zugestimmt hat. Andernfalls kann es je nach Land gegen Gesetze verstoßen, etwa gegen das Urheberrecht (Umgehen von Schutzmaßnahmen)."] =
            "This lifts the permissions of the file (e.g. printing, copying, changing) without your knowing the permissions password. It is "
            + "only allowed if it is your own file or the owner or rights holder has consented. Otherwise it may break the law, depending on the "
            + "country, for example copyright law (circumventing protection measures).",
        ["Ich bin berechtigt"] = "I am entitled",
        ["Ohne Rechte-Passwort entfernen"] = "Remove without the permissions password",
        ["Auch das Passwort zum Öffnen entfernen"] = "Also remove the open password",
        ["Gilt sofort in der offenen Datei, in der Datei selbst ab dem nächsten Speichern. Schutzmaßnahmen an fremden, urheberrechtlich geschützten Werken zu umgehen, ist ohne Erlaubnis nicht erlaubt."] =
            "Applies at once to the open file, to the file itself from the next save. Circumventing protection of other people's copyrighted works is not allowed without permission.",
        ["Entfernen"] = "Remove",

        // Print type and poster (see KONZEPT.md, section 5.11)
        ["Druckart"] = "Print type",
        ["Normal"] = "Normal",
        ["Poster"] = "Poster",
        ["Normal: eine oder mehrere Seiten pro Blatt. Broschüre: zwei Seiten je Blattseite, in der Mitte gefalzt. Poster: eine Seite vergrößert auf mehrere Blätter zum Zusammenkleben."] =
            "Normal: one or more pages per sheet. Booklet: two pages per side, folded in the middle. Poster: one page enlarged onto several sheets to glue together.",
        ["POSTER"] = "POSTER",
        ["Postergröße"] = "Poster size",
        ["Postergröße in Prozent"] = "Poster size in percent",
        ["Eigene Größe (Prozent)"] = "Custom size (percent)",
        ["{0} ({1} × {2} mm)"] = "{0} ({1} × {2} mm)",
        ["Die Seite wird auf dieses Format vergrößert (im Hochformat, wenn die Seite hoch ist, sonst quer) — oder um einen eigenen Prozentwert"] =
            "The page is enlarged to this format (portrait if the page is portrait, otherwise landscape) — or by a percentage of your own",
        ["Klebekante"] = "Glue edge",
        ["Klebekante in mm"] = "Glue edge in mm",
        ["So weit überlappen benachbarte Blätter: ein Rand zum Kleben, und nichts fehlt, wenn man nicht ganz genau schneidet"] =
            "Neighbouring sheets overlap by this much: an edge for gluing, and nothing is missing if the cut is not exact",
        ["Schnittmarken"] = "Cut marks",
        ["Marken an den Ecken: dort den Rand abschneiden; kurze Striche zeigen, wo das Nachbarblatt anliegt"] =
            "Marks at the corners: cut off the margin there; short strokes show where the neighbouring sheet goes",
        ["Passkreuze"] = "Registration marks",
        ["Kreuze in der Mitte der Klebekante — sie stehen auf beiden Nachbarblättern an derselben Stelle und helfen beim Ausrichten"] =
            "Crosses in the middle of the glue edge — they are at the same spot on both neighbouring sheets and help with aligning",
        ["Klein am Rand jedes Blatts: Name im Raster (z. B. B2), Seite und Größe des Rasters"] =
            "Small at the edge of each sheet: name in the grid (e.g. B2), page and grid size",
        ["{0} × {1} = {2} Blätter · {3} × {4} mm"] = "{0} × {1} = {2} sheets · {3} × {4} mm",
        ["Übersicht"] = "Overview",
        ["Die ganze Seite mit dem Raster der Blätter — ein Klick auf ein Blatt zeigt es groß"] = "The whole page with the grid of sheets — click a sheet to see it large",
        ["Das einzelne Blatt, wie es aus dem Drucker kommt, mit Marken und Beschriftung"] = "The single sheet as it comes out of the printer, with marks and labels",
        ["Poster-Übersicht"] = "Poster overview",
        ["Blatt {0} von {1} · {2}"] = "Sheet {0} of {1} · {2}",
        ["Das Poster bräuchte mehr als {0} Blätter je Seite — bitte kleiner wählen."] = "The poster would need more than {0} sheets per page — please choose a smaller size.",

        // Compressor: method per image type (see KONZEPT.md, section 5.12)
        ["BILDGRÖSSE"] = "IMAGE SIZE",
        ["FOTOS"] = "PHOTOS",
        ["GRAFIKEN UND BILDSCHIRMFOTOS"] = "GRAPHICS AND SCREENSHOTS",
        ["SCHWARZWEISS-SCANS"] = "BLACK-AND-WHITE SCANS",
        ["FARBSCANS"] = "COLOUR SCANS",
        ["WO ES GELESEN WIRD"] = "WHERE IT CAN BE READ",
        ["Verfahren"] = "Method",
        ["Verfahren für Fotos"] = "Method for photos",
        ["Verfahren für Grafiken"] = "Method for graphics",
        ["Verfahren für Schwarzweiß-Scans"] = "Method for black-and-white scans",
        ["Verfahren für Farbscans"] = "Method for colour scans",
        ["Mehr über das Verfahren für Fotos"] = "More about the method for photos",
        ["Mehr über das Verfahren für Grafiken"] = "More about the method for graphics",
        ["Mehr über das Verfahren für Schwarzweiß-Scans"] = "More about the method for black-and-white scans",
        ["Mehr über das Verfahren für Farbscans"] = "More about the method for colour scans",
        ["Mehr über das Packverfahren"] = "More about the packing method",
        ["Packen"] = "Packing",
        ["Packverfahren"] = "Packing method",
        ["Farben"] = "Colours",
        ["Glätten"] = "Dithering",
        ["Mindestqualität"] = "Minimum quality",
        ["Mindestqualität der Palette"] = "Minimum quality of the palette",
        ["Höchstens so viele Farben"] = "At most this many colours",
        ["Schwarzweiß-Scans als 1-Bit-Bild"] = "Black-and-white scans as 1-bit images",
        ["Bilder, die schärfer sind als nötig (mehr als das 1,5-Fache der Auflösung), werden verkleinert und neu gepackt. Aus: Bilder bleiben, wie sie sind — nur verlustfreie Schritte."] =
            "Images sharper than needed (more than 1.5 times the resolution) are reduced and repacked. Off: images stay as they are — lossless steps only.",
        ["Wie viele Bildpunkte je Zoll übrig bleiben: Bildschirm 96–120 dpi, Tablet 150 dpi, Druck 300 dpi. Weniger heißt kleiner, aber unschärfer."] =
            "How many pixels per inch remain: screen 96–120 dpi, tablet 150 dpi, print 300 dpi. Less means smaller but blurrier.",
        ["Weniger heißt kleiner, aber mit sichtbaren Blöcken und Schlieren an Kanten — im Vorher/Nachher hineinzoomen. Greift nur, wenn Bilder neu gepackt werden dürfen."] =
            "Less means smaller, but with visible blocks and smears at edges — zoom in on before/after. Only applies when images may be repacked.",
        ["Verlustfrei, ohne Einstellungen: das Bild bleibt Punkt für Punkt gleich."] = "Lossless, no settings: the image stays the same pixel for pixel.",
        ["Höchstens so viele Farben in der Farbliste. Weniger heißt kleiner, aber Verläufe werden stufig. Bilder mit weniger Farben bleiben genau."] =
            "At most this many colours in the colour list. Fewer means smaller, but gradients get steps. Images with fewer colours stay exact.",
        ["Streut feine Punkte, damit Verläufe weich statt streifig aussehen. Macht die Datei aber deutlich größer — meist ist 0 % richtig."] =
            "Scatters fine dots so gradients look smooth instead of banded. Makes the file noticeably larger, though — 0 % is usually right.",
        ["So gut muss die Palette das Bild treffen. Schafft sie es nicht (etwa bei Fotos), wird das Bild als JPEG gepackt. Höher heißt: seltener Palette, dafür nie sichtbar anders."] =
            "How closely the palette must match the image. If it cannot (photos, for example), the image is packed as JPEG. Higher means: palette less often, but never visibly different.",
        ["Scans, die nur aus Schwarz und Weiß bestehen, werden viel kleiner. Fast schwarzweiße (leichtes Grau vom Scanner) nur, wenn Bilder neu gepackt werden dürfen."] =
            "Scans that are only black and white become much smaller. Nearly black-and-white ones (light grey from the scanner) only when images may be repacked.",
        ["Farbige Scans werden wie Fotos behandelt — mit Auflösung und Qualität von oben."] = "Colour scans are treated like photos — with the resolution and quality above.",
        ["Wie Text, Schriften und Zeichnungen gepackt werden. Flate kann jedes Programm lesen."] = "How text, fonts and drawings are packed. Every program can read Flate.",
        ["Grün: ja, orange: teilweise, rot: nein."] = "Green: yes, orange: partial, red: no.",
        ["(Stand Oktober 2026)"] = "(as of October 2026)",
        ["JPEG"] = "JPEG",
        ["JPEG XL"] = "JPEG XL",
        ["Flate"] = "Flate",
        ["Flate mit Prädiktor"] = "Flate with predictor",
        ["Palette"] = "Palette",
        ["CCITT G4"] = "CCITT G4",
        ["JBIG2"] = "JBIG2",
        ["MRC"] = "MRC",
        ["Brotli"] = "Brotli",
        ["Wie Fotos"] = "Like photos",
        ["Erkennung"] = "Detection",
        ["Schriftfarben"] = "Text colours",
        ["Empfindlichkeit der Schrift-Erkennung"] = "Sensitivity of the text detection",
        ["Höchstens so viele Schriftfarben"] = "At most this many text colours",
        ["Alle Einstellungen auf die Vorgabe „E-Book“ zurückstellen"] = "Reset all settings to the default “E-book”",
        ["Höher findet auch blasse Schrift und Bleistift, nimmt aber eher Flecken und Papierstruktur mit. Niedriger lässt Blasses im weichen Hintergrund."] =
            "Higher also finds faint text and pencil but is more likely to pick up stains and paper texture. Lower leaves faint marks in the soft background.",
        ["1: alle Schrift in einer Farbe. Mehr hält Kuli, Stempel und farbige Markierungen in ihrer Farbe."] =
            "1: all text in one colour. More keeps ballpoint pen, stamps and coloured marks in their colour.",
        ["Nur Seiten, die als Textscan erkannt werden; Fotos und Grafiken bleiben beim üblichen Weg. Die Schrift bleibt scharf, das Papier wird klein; ein unsichtbarer OCR-Text bleibt erhalten. Greift nur, wenn Bilder neu gepackt werden dürfen."] =
            "Only pages recognised as text scans; photos and graphics take the usual route. The text stays sharp, the paper becomes small; an invisible OCR text is kept. Only applies when images may be repacked.",
        ["Schrift glätten (600 dpi)"] = "Smooth text (600 dpi)",
        ["Schrift doppelt so fein wie ein 300-dpi-Scan: glatte Kanten wie im Original, die Datei wird etwas größer (etwa ein Sechstel). Aus: Schrift in 300 dpi, kantiger."] =
            "Text twice as fine as a 300 dpi scan: smooth edges like the original, the file gets somewhat larger (about a sixth). Off: text at 300 dpi, more jagged.",
        ["Papier glätten"] = "Smooth paper",
        ["Körnung des Papiers und durchscheinende Rückseiten werden zu einem gleichmäßigen Papierton — ruhiger und etwas kleiner. Stempel, Markierungen und getönte Felder bleiben."] =
            "Paper grain and show-through from the back become an even paper tone — calmer and slightly smaller. Stamps, highlights and tinted boxes stay.",
        ["PDF-Norm"] = "PDF standard",
        ["PDF/A"] = "PDF/A",
        ["Verbreitete Leser"] = "Common readers",
        ["seit PDF {0}"] = "since PDF {0}",
        ["lesen es"] = "read it",
        ["erlaubt"] = "allowed",
        ["nicht erlaubt"] = "not allowed",
        ["noch nicht genormt"] = "not yet standardised",
        ["bisher keiner"] = "none so far",
        ["noch nicht in der Norm (Erweiterung der PDF Association)"] = "not yet in the standard (extension of the PDF Association)",
        ["viele noch nicht"] = "many not yet",
        ["geplant – die PDF-Norm dafür ist noch nicht veröffentlicht"] = "planned – the PDF standard for it has not been published yet",
        ["unbekannt"] = "unknown",
        ["Für Fotos. Spart viel Platz, indem es feine Details weglässt, die man kaum sieht. Jedes Programm kann es lesen — darum der Standard."] =
            "For photos. Saves a lot of space by leaving out fine details you hardly see. Every program can read it — that is why it is the default.",
        ["Ein sehr effizientes neues Bildformat. Für PDF angekündigt, aber noch nicht genormt — bisher kann es kein Programm in PDFs lesen."] =
            "A very efficient new image format. Announced for PDF but not yet standardised — no program can read it in PDFs so far.",
        ["Verlustfrei — nichts geht verloren. Jeder Bildpunkt wird aus seinen Nachbarn vorhergesagt, gespeichert wird nur die Abweichung. Bilder mit höchstens 256 Farben werden dabei zur genauen Farbliste."] =
            "Lossless — nothing is lost. Each pixel is predicted from its neighbours and only the difference is stored. Images with at most 256 colours become an exact colour list.",
        ["Für Logos, Diagramme und Bildschirmfotos: die Datei merkt sich eine Liste von höchstens 256 Farben und je Punkt nur die Nummer. Oft deutlich kleiner und schärfer als JPEG; echte Fotos bleiben JPEG."] =
            "For logos, diagrams and screenshots: the file keeps a list of at most 256 colours and only the number for each pixel. Often much smaller and sharper than JPEG; real photos stay JPEG.",
        ["Für reine Schwarzweiß-Scans wie Briefe und Formulare: das Faxverfahren — alt, klein und überall lesbar."] =
            "For pure black-and-white scans such as letters and forms: the fax method — old, small and readable everywhere.",
        ["Der moderne Nachfolger von G4: dieselben Schwarzweiß-Punkte, etwa ein Drittel kleiner gepackt. Verlustfrei — jeder Bildpunkt bleibt, wie er ist. PDF-Knead vergleicht keine Zeichen miteinander, darum kann nie eine Ziffer vertauscht werden."] =
            "The modern successor to G4: the same black-and-white dots, packed about a third smaller. Lossless — every pixel stays as it is. PDF-Knead never compares characters with each other, so a digit can never be swapped.",
        ["Farbige Scans werden wie Fotos behandelt: verkleinert und als JPEG gepackt."] = "Colour scans are treated like photos: reduced and packed as JPEG.",
        ["Für farbige Scans: Schrift wird scharf in Schwarzweiß gespeichert, der Hintergrund klein und weich. Der Text bleibt gestochen scharf, die Datei wird ein Vielfaches kleiner. Die Schrift ist mit JBIG2 gepackt (Vorgabe) — mit G4 statt JBIG2 liest es jeder Leser seit 1993."] =
            "For colour scans: text is stored sharply in black and white, the background small and soft. Text stays crisp and the file becomes many times smaller. The text is packed with JBIG2 (default) — with G4 instead of JBIG2 every reader since 1993 can read it.",
        ["Das übliche Packverfahren für Text, Schriften und Zeichnungen — verlustfrei und überall lesbar."] =
            "The usual packing method for text, fonts and drawings — lossless and readable everywhere.",
        ["Ein neueres Packverfahren, rund ein Fünftel kleiner als Flate. Verbreitete Leser können solche Dateien oft noch nicht öffnen — nur wählen, wenn klar ist, womit die Datei gelesen wird. Nicht für PDF/A."] =
            "A newer packing method, about a fifth smaller than Flate. Common readers often cannot open such files yet — only choose it if you know what the file will be read with. Not for PDF/A.",
        ["Flate – stark (langsamer)"] = "Flate – strong (slower)",
        ["Bearbeitungsmodus aktiv — Felder auswählen, verschieben, in der Größe ändern und löschen. Esc oder „Beenden“ zum Ausfüllen."] =
            "Edit mode on — select, move, resize and delete fields. Esc or “End” to fill in the form.",
        ["Beenden"] = "End",
        ["Modus beenden"] = "End mode",
        ["Formen"] = "Shapes",
        ["Schrift automatisch verkleinern"] = "Shrink font automatically",
        ["Feste Schriftgröße"] = "Fixed font size",
        ["Die gewählte Größe ist die Startgröße — passt der Text nicht mehr hinein, wird die Schrift kleiner (auch mehrzeilig). Bei „Automatisch“ geschieht das ohnehin. In manchen anderen PDF-Programmen richtet sich die Startgröße beim Tippen nach der Feldhöhe."] =
            "The chosen size is the starting size — when the text no longer fits, the font gets smaller (also on several lines). With “Automatic” this happens anyway. In some other PDF programs the starting size follows the field height while typing.",
        ["Bildgröße ändern"] = "Change image size",
        ["Breite (mm)"] = "Width (mm)",
        ["Höhe (mm)"] = "Height (mm)",
        ["Breite in Millimetern"] = "Width in millimetres",
        ["Höhe in Millimetern"] = "Height in millimetres",
        ["Breite des Bilds — mit geschlossener Kette ändert sich die Höhe mit"] = "Width of the image — with the chain closed the height changes too",
        ["Höhe des Bilds — mit geschlossener Kette ändert sich die Breite mit"] = "Height of the image — with the chain closed the width changes too",
        ["Gespeichert wird das Bild mit 300 dpi in dieser Größe (mit Lanczos verkleinert) — scharf im Druck, die Datei bleibt schlank."] =
            "The image is saved at 300 dpi in this size (reduced with Lanczos) — sharp in print, the file stays lean.",
        ["Kanten betonen, etwa bei leicht unscharfen Fotos — 0 % lässt das Bild, wie es ist"] = "Emphasise edges, e.g. for slightly blurred photos — 0 % leaves the image as it is",
        ["Kette geschlossen: Seitenverhältnis bleibt, auch an den Griffen (Umschalt beim Ziehen kehrt es um). Kette offen: Breite und Höhe frei — das Bild wird gestreckt."] =
            "Chain closed: the aspect ratio stays, also at the handles (Shift while dragging reverses it). Chain open: width and height are free — the image is stretched.",
        ["Schärfe ändern"] = "Change sharpness",
