        ["Linie ziehen (mit Umschalt: waagerecht, senkrecht oder 45°)"] = "Drag a line (with Shift: horizontal, vertical or 45°)",
        ["Pfeil ziehen — die Spitze kommt ans Ende (mit Umschalt: waagerecht, senkrecht oder 45°)"] =
