        ["Feldname"] = "Field name",
        ["Kammfeld, {0} Zeichen"] = "Comb field, {0} characters",
        ["Keine Felder gefunden — nichts auf den Seiten sieht nach einer Linie oder einem leeren Kästchen zum Ausfüllen aus."] = "No fields found — nothing on the pages looks like a line or an empty box to fill in.",
        ["Keinen Vorschlag anhaken"] = "Tick no proposal",
        ["Option „{0}“"] = "Option “{0}”",
        ["Schließen, ohne Felder anzulegen"] = "Close without creating fields",
        ["Schlägt Felder an Linien, Kästchen und Tabellen der Seiten vor, auch in Scans — Sie prüfen, benennen und übernehmen. Mit den KI-Modellen liest es Scans und findet auch nicht gezeichnete Felder."] =
            "Proposes fields at the lines, boxes and tables of the pages, also in scans — you check, name and apply them. With the AI models it reads scans and also finds fields that are not drawn.",
        ["Seite {0} von {1} …"] = "Page {0} of {1} …",
        ["Suche Felder …"] = "Looking for fields …",
        ["Textfeld, mehrzeilig"] = "Text field, multi-line",
        ["Vorschläge an Linien, Kästchen und Tabellen der Seiten, auch in Scans — gestrichelt auf der Seite, ein Klick dort hakt an oder ab. Erst „Übernehmen“ legt die Felder an."] =
            "Proposals at lines, boxes and tables of the pages, also in scans — dashed on the page, a click there ticks or unticks. Only “Apply” creates the fields.",
        ["Den Text der gescannten Seite hat die Texterkennung gelesen."] = "The text recognition read the text of the scanned page.",
