        ["Nach „stream“ steht nicht CR LF oder LF."] = "“stream” is not followed by CR LF or LF.",
        ["Vor „endobj“ fehlt das Zeilenende."] = "“endobj” is not preceded by an end-of-line marker.",
        ["Nach „endobj“ fehlt das Zeilenende."] = "“endobj” is not followed by an end-of-line marker.",
        ["Eine hexadezimale Zeichenkette enthält andere Zeichen als Ziffern."] = "A hexadecimal string contains characters other than digits.",
        ["Eine hexadezimale Zeichenkette hat eine ungerade Zahl von Ziffern."] = "A hexadecimal string has an odd number of digits.",
