        ["Ein Grafikzustand legt den Ursprung des Rasters fest (/{0})."] = "A graphics state sets the origin of the halftone (/{0}).",
        ["Ein Raster hat eine Transferfunktion (/TransferFunction), wo ISO 32000 keine vorsieht, oder keine, wo sie verlangt ist."] = "A halftone has a transfer function (/TransferFunction) where ISO 32000 provides none, or none where one is required.",
        ["Ein JPEG-2000-Bild nutzt den Farbraum CIEJab."] = "A JPEG 2000 image uses the colour space CIEJab.",
        ["Eine Bildmaske hat eine andere Farbtiefe als 1 Bit (/BitsPerComponent {0})."] = "An image mask has a bit depth other than 1 (/BitsPerComponent {0}).",
        ["Der XMP-Paketkopf enthält „bytes“."] = "The XMP packet header contains “bytes”.",
        ["Der XMP-Paketkopf enthält „encoding“."] = "The XMP packet header contains “encoding”.",
        ["Die Metadaten nennen einen anderen Teil von PDF/A ({0})."] = "The metadata name another part of PDF/A ({0}).",
        ["Die Metadaten nennen keine gültige Stufe von PDF/A ({0})."] = "The metadata name no valid level of PDF/A ({0}).",
        ["Die Metadaten nennen nicht die Ausgabe 2020 von PDF/A-4 (pdfaid:rev)."] = "The metadata do not name the 2020 revision of PDF/A-4 (pdfaid:rev).",
        ["Bei einem Anhang fehlt die Dateiart (/Subtype als MIME-Typ)."] = "An attachment lacks its file type (/Subtype as a MIME type).",
        ["Ein Grafikzustand hat ein Raster anderer Art als 1 oder 5 (/HalftoneType)."] = "A graphics state has a halftone of a type other than 1 or 5 (/HalftoneType).",
        ["Ein Raster nennt einen Rasternamen (/HalftoneName)."] = "A halftone names a halftone name (/HalftoneName).",
        ["Bei einer Dateiangabe fehlt die Beziehung zum Dokument (/AFRelationship)."] = "A file specification lacks its relationship to the document (/AFRelationship).",
        ["Bei der Schrift „{0}“ fehlt /FirstChar."] = "The font “{0}” lacks /FirstChar.",
        ["Bei der Schrift „{0}“ fehlt /LastChar."] = "The font “{0}” lacks /LastChar.",
        ["Die Breitenangaben der Schrift „{0}“ fehlen oder sind unvollständig (/Widths)."] = "The widths of the font “{0}” are missing or incomplete (/Widths).",
        ["Das Dokument enthält eine unzulässige benannte Aktion ({0})."] = "The document contains a named action that is not allowed ({0}).",
        ["Eine Ebenen-Konfiguration hat keinen Namen."] = "A layer configuration has no name.",
        ["Zwei Ebenen-Konfigurationen haben denselben Namen."] = "Two layer configurations have the same name.",
        ["Eine Dateiangabe ist keinem Teil des Dokuments zugeordnet (/AF)."] = "A file specification is not associated with any part of the document (/AF).",
        ["Die Datei beginnt nicht mit der Kennung einer PDF-Version 2.x."] = "The file does not begin with the identification of a PDF version 2.x.",
        ["Die Datei hat ein Dokumentinfo-Wörterbuch (/Info), das PDF/A-4 nicht erlaubt."] = "The file has a document information dictionary (/Info), which PDF/A-4 does not allow.",
        ["Das Dokumentinfo-Wörterbuch (/Info) enthält mehr als das Änderungsdatum."] = "The document information dictionary (/Info) contains more than the modification date.",
        ["Die Schrift „{0}“ zeigt Zeichen ohne Unicode-Zuordnung."] = "The font “{0}” shows characters without a Unicode mapping.",
        ["Die Unicode-Zuordnung der Schrift „{0}“ enthält unzulässige Werte (0, U+FEFF, U+FFFE)."] = "The Unicode mapping of the font “{0}” contains invalid values (0, U+FEFF, U+FFFE).",
        ["Das Dokument stellt Anforderungen an den Leser (/Requirements)."] = "The document states requirements for the reader (/Requirements).",
        ["Der Katalog nennt eine PDF-Version vor 2.0 (/Version)."] = "The catalogue names a PDF version before 2.0 (/Version).",
        ["PDF/A-4f verlangt mindestens einen Anhang (/EmbeddedFiles)."] = "PDF/A-4f requires at least one attachment (/EmbeddedFiles).",
        ["Eine Ausgabebedingung verweist auf ein Farbprofil außerhalb der Datei (/DestOutputProfileRef)."] = "An output intent refers to a colour profile outside the file (/DestOutputProfileRef).",
        ["Ein Bild hat eine unzulässige Farbtiefe (/BitsPerComponent {0})."] = "An image has an invalid bit depth (/BitsPerComponent {0}).",
        ["Ein Ersatztext (/ActualText) enthält Zeichen aus dem privaten Bereich von Unicode."] = "A replacement text (/ActualText) contains characters from the private use area of Unicode.",
        // Messen (Ablaufplan 7.6)
        ["Anfang und Ende anklicken."] = "Click the start and the end.",
        ["Die Ecken der Fläche anklicken; Doppelklick oder Enter schließt sie. Bögen: Strg+Umschalt+Klick setzt einen Bogenpunkt, der nächste Klick beendet den Bogen durch ihn; Strg+Alt+Klick setzt das Ende eines Bogens, der ohne Knick anschließt."] =
            "Click the corners of the area; a double-click or Enter closes it. Arcs: Ctrl+Shift+click sets an arc point, the next click ends the arc through it; Ctrl+Alt+click sets the end of an arc that goes on without a bend.",
        ["Die Messungen von der Seite nehmen (in der Datei steht nichts davon)"] = "Take the measurements off the page (nothing of them is in the file)",
        ["Drei Punkte: Schenkel, Scheitel, Schenkel."] = "Three points: arm, vertex, arm.",
        ["Fläche"] = "Area",
        ["Kein Maßstab auf der Seite — gemessen wird das Papier (mm)."] = "No scale on the page — the paper is measured (mm).",
        ["Linienzug"] = "Polyline",
        ["Misst den Abstand zwischen zwei Punkten."] = "Measures the distance between two points.",
        ["Klick"] = "Click",
        ["Klick — die Messung ist fertig"] = "Click — the measurement is done",
        ["Misst die Länge aus mehreren Abschnitten: Geraden, Knicke und Bögen."] =
            "Measures the length of several sections: straight lines, corners and arcs.",
        ["Gerade"] = "Straight line",
        ["Bogen"] = "Arc",
        ["Strg+Umschalt+Klick auf einen Punkt des Bogens, dann sein Ende anklicken"] = "Ctrl+Shift+click a point of the arc, then click its end",
        ["Bogen tangential"] = "Tangent arc",
        ["Strg+Alt+Klick auf sein Ende — schließt ohne Knick an; nach dem ersten Punkt mit Strg+Alt die Richtung ziehen (ein Klick setzt einen Bogenpunkt)"] = "Ctrl+Alt+click its end — joins without a corner; after the first point drag the direction with Ctrl+Alt (a click sets an arc point)",
        ["Bogen tangential kippen"] = "Flip tangent arc",
        ["Leertaste"] = "Space bar",
        ["Doppelklick oder Enter"] = "Double-click or Enter",
        ["Doppelklick auf einen fertigen Linienzug, dann am Anfang oder Ende weiterklicken"] =
            "Double-click a finished polyline, then go on clicking at its start or end",
        ["Misst Fläche und Umfang — auch mit gebogenen Kanten."] = "Measures area and perimeter — also with curved edges.",
        ["Ecke"] = "Corner",
        ["Misst den Winkel zwischen zwei Schenkeln."] = "Measures the angle between two legs.",
        ["Erster Schenkel"] = "First leg",
        ["Klick auf einen Punkt"] = "Click a point",
        ["Scheitel"] = "Vertex",
        ["Zweiter Schenkel"] = "Second leg",
        ["Klick auf einen Punkt — die Messung ist fertig"] = "Click a point — the measurement is done",
        ["Misst einen Kreis oder Bogen über Punkte auf seinem Rand."] = "Measures a circle or arc by points on its edge.",
        ["Randpunkte"] = "Points on the edge",
        ["Klick — mindestens drei; der erste und der letzte sind die Enden"] = "Click — at least three; the first and the last are the ends",
        ["Ganzer Kreis"] = "Whole circle",
        ["den letzten Punkt auf den ersten setzen"] = "put the last point on the first",
        ["Längen, Flächen, Winkel und Radien messen — mit dem Maßstab der Seite, sonst in Millimetern des Papiers"] = "Measure lengths, areas, angles and radii — with the scale of the page, otherwise in millimetres of the paper",
        ["Maßstab der Seite"] = "Scale of the page",
        ["Maßstab: {0}"] = "Scale: {0}",
        ["Messen"] = "Measure",
        ["Messen beenden"] = "End measuring",
        ["Messen beenden (die Messungen verschwinden)"] = "End measuring (the measurements disappear)",
        ["Messungen"] = "Measurements",
        ["Messungen entfernen"] = "Remove measurements",
        ["Punkte nacheinander anklicken; Doppelklick oder Enter beendet. Bögen: Strg+Umschalt+Klick setzt einen Bogenpunkt, der nächste Klick beendet den Bogen durch ihn; Strg+Alt+Klick setzt das Ende eines Bogens, der ohne Knick anschließt — so auch S-Kurven."] =
            "Click the points one after another; a double-click or Enter ends. Arcs: Ctrl+Shift+click sets an arc point, the next click ends the arc through it; Ctrl+Alt+click sets the end of an arc that goes on without a bend — S-curves too.",
        ["Punkte rasten an Linien der Zeichnung ein, mit Alt frei; Linien rasten gerade ein (0°, 45°, 90° …), mit Umschalt beliebiger Winkel. Esc verwirft, Rücktaste nimmt den letzten Punkt zurück."] = "Points snap to lines of the drawing, freely with Alt; lines snap straight (0°, 45°, 90° …), any angle with Shift. Esc discards, Backspace takes back the last point.",
        ["Kreis/Bogen"] = "Circle/arc",
        ["Mindestens drei Punkte auf dem Kreis oder Bogen — der erste und der letzte sind seine Enden; Doppelklick oder Enter beendet. Erster und letzter Punkt gleich: der ganze Kreis."] = "At least three points on the circle or arc — the first and the last are its ends; a double-click or Enter ends. First and last point the same: the whole circle.",
        ["Bogen {0} · {1} · Punkte bis {2} vom Kreis"] = "Arc {0} · {1} · points up to {2} off the circle",
        ["Bogen {0} · {1}"] = "Arc {0} · {1}",
        // Messen: kalibrieren mit Lupe (Ablaufplan 7.6 g)
        ["Maßstab"] = "Scale",
        ["Strecke auf dem Papier: {0}"] = "Line on the paper: {0}",
        ["Anfang der bekannten Strecke anklicken (etwa der Maßstabsleiste) — die Lupe hilft beim genauen Setzen."] = "Click the start of the known line (such as the scale bar) — the magnifier helps to place it exactly.",
        ["Ende der Strecke anklicken."] = "Click the end of the line.",
        ["Wirkliche Länge der Strecke eingeben — daraus ergibt sich der Maßstab."] = "Enter the real length of the line — this gives the scale.",
        ["Maßstab unbekannt? „Kalibrieren“ und eine Strecke bekannter Länge mit Anfang und Ende setzen."] = "Scale unknown? “Calibrate” and set the start and end of a line of known length.",
        ["Anfang und Ende einer Strecke bekannter Länge setzen (etwa der Maßstabsleiste des Plans) — mit Lupe; dann ihre wirkliche Länge eingeben"] = "Set the start and end of a line of known length (such as the scale bar of the plan) — with a magnifier; then enter its real length",
        ["entspricht"] = "is",
        ["Wirkliche Länge der Strecke"] = "Real length of the line",
        ["Gilt für"] = "Applies to",
        ["diese Seite"] = "this page",
        ["alle Seiten"] = "all pages",
        ["Den Maßstab für alle Seiten der Datei festlegen (ein Rückgängig-Schritt)"] = "Set the scale for all pages of the file (one undo step)",
        ["Den Maßstab festlegen; er wird mit der Datei gespeichert, andere Programme messen dann dasselbe"] = "Set the scale; it is saved with the file, other programs then measure the same",
        // Messen: als Bemaßung einfügen (Ablaufplan 7.6 f)
        ["Die Seite hatte eigene Maßstäbe für Teilbereiche — der neue gilt jetzt auch dort."] = "The page had scales of its own for parts of it — the new one now holds there too.",
        ["Als Bemaßung einfügen"] = "Insert as dimension",
        ["Messungen als Bemaßungen einfügen"] = "Insert measurements as dimensions",
        ["Alle als Bemaßung einfügen"] = "Insert all as dimensions",
        ["Als Bemaßung eingefügt — sie wird mit der Datei gespeichert; andere Programme messen dasselbe."] = "Inserted as a dimension — it is saved with the file; other programs measure the same.",
        ["{0} Messungen als Bemaßungen eingefügt — sie werden mit der Datei gespeichert; andere Programme messen dasselbe."] = "{0} measurements inserted as dimensions — they are saved with the file; other programs measure the same.",
        ["Die Messung als Bemaßung in die Seite setzen — sie wird mit der Datei gespeichert, andere Programme zeigen sie und messen dasselbe"] = "Put the measurement into the page as a dimension — it is saved with the file, other programs show it and measure the same",
        ["Alle Messungen als Bemaßungen in die Seiten setzen (ein Rückgängig-Schritt) — sie werden mit der Datei gespeichert"] = "Put all measurements into the pages as dimensions (one undo step) — they are saved with the file",
        // Messen: Auswahl und Einstellungen (Ablaufplan 7.6 e3)
        ["Als Linienzug"] = "As polyline",
        ["Als Bogen"] = "As arc",
        ["Die Punkte liegen auf einer Geraden — kein Bogen."] = "The points lie on a straight line — no arc.",
        ["Maßstab {0} für alle {1} Seiten festgelegt — er wird mit der Datei gespeichert."] = "Scale {0} set for all {1} pages — it is saved with the file.",
        ["wie in der Datei"] = "as in the file",
        ["Wie viele Stellen nach dem Komma die Werte zeigen — „wie in der Datei“ nimmt die Zahlenformate des Maßstabs"] = "How many decimals the values show — “as in the file” takes the number formats of the scale",
        ["Punkte rasten an der Zeichnung ein"] = "Points snap to the drawing",
        ["Gerade Linien einrasten (0°, 45°, 90° …)"] = "Snap lines straight (0°, 45°, 90° …)",
        ["Lupe beim Setzen der Punkte"] = "Magnifier while setting points",
        ["Beim Ausschalten nach Messungen fragen, die nicht in der PDF sind"] = "When switching off, ask about measurements that are not in the PDF",
        ["Messungen sind zuerst nur Anzeige; beim Ausschalten von „Messen“ fragt PDF-Knead, ob sie als Bemaßung in die PDF sollen"] =
            "Measurements are shown only at first; when “Measure” is switched off, PDF Knead asks whether they should go into the PDF as dimensions",
        ["Messung abschließen?"] = "Finish the measurement?",
        ["Die Messung ist noch nicht abgeschlossen und nicht in der PDF. Abgeschlossen bleibt sie sichtbar, solange „Messen“ an ist; in die PDF kommt sie als Bemaßung, die mit der Datei gespeichert wird."] =
            "The measurement is not finished yet and not in the PDF. Finished, it stays visible while “Measure” is on; it goes into the PDF as a dimension, which is saved with the file.",
        ["Abschließen"] = "Finish",
        ["Fortsetzen"] = "Continue",
        ["Den Linienzug weiterzeichnen — der nächste Klick setzt am näheren Ende an (auch Doppelklick auf seine Linie)"] =
            "Draw the polyline on — the next click goes on at the nearer end (a double-click on its line does the same)",
        ["Linienzug fortsetzen: der nächste Klick setzt am näheren Ende an — Enter beendet, Esc fragt."] =
            "Continuing the polyline: the next click goes on at the nearer end — Enter ends, Esc asks.",
        ["Bemaßung fortsetzen"] = "Continue dimension",
        ["Der Code ragt über den Blattrand — so lässt er sich nicht vollständig lesen."] = "The code reaches beyond the edge of the page — it cannot be read whole like this.",
        ["Bild ragt über den Blattrand"] = "Image reaches beyond the edge of the page",
        ["Der Teil außerhalb des Blatts ist unsichtbar und wird nicht gedruckt, bliebe aber in der Datei — jeder könnte ihn herauslösen. Soll er abgeschnitten werden?"] =
            "The part outside the page is invisible and not printed, but it would stay in the file — anyone could take it out. Cut it off?",
        ["Abschneiden"] = "Cut off",
        ["Nicht mehr fragen (etwa bei Anschnitt für den Druck; wieder einschaltbar beim Bild)"] = "Don’t ask again (for bleed in print, say; can be switched on again with the image)",
        ["Am Blattrand abschneiden"] = "Cut off at the page edge",
        ["Blattrand"] = "Page edge",
        ["Den Teil des Bildes außerhalb des Blatts entfernen — unsichtbar bliebe er in der Datei und ließe sich herauslösen"] =
            "Remove the part of the image outside the page — invisible, it would stay in the file and could be taken out",
        ["Fragen, wenn ein Bild über den Blattrand ragt"] = "Ask when an image reaches beyond the page edge",
        ["Aus, etwa bei Anschnitt für den Druck: das Bild bleibt ganz, ohne Frage"] = "Off, for bleed in print, say: the image stays whole, without a question",
        ["Punkt einfügen"] = "Insert point",
        ["Punkt entfernen"] = "Remove point",
        ["Bei dieser Messung lassen sich keine Punkte entfernen."] = "No points can be removed from this measurement.",
        ["Ein Bogen braucht mindestens drei Punkte."] = "An arc needs at least three points.",
        ["Eine Fläche braucht mindestens drei Punkte."] = "An area needs at least three points.",
        ["Ein Linienzug braucht mindestens zwei Punkte."] = "A polyline needs at least two points.",
        ["Abschließen und in die PDF einfügen"] = "Finish and insert into the PDF",
        ["Verwerfen"] = "Discard",
        ["Weiter messen"] = "Keep measuring",
        ["Messung in die PDF übernehmen?"] = "Put the measurement into the PDF?",
        ["Messungen in die PDF übernehmen?"] = "Put the measurements into the PDF?",
        ["In „{0}“ ist eine Messung nicht in der PDF — ohne Einfügen ist sie fort, sobald „Messen“ aus ist. Als Bemaßung eingefügt wird sie mit der Datei gespeichert; andere Programme messen dasselbe."] =
            "In “{0}” one measurement is not in the PDF — unless it is inserted, it is gone once “Measure” is off. Inserted as a dimension, it is saved with the file; other programs measure the same.",
        ["In „{0}“ sind {1} Messungen nicht in der PDF — ohne Einfügen sind sie fort, sobald „Messen“ aus ist. Als Bemaßungen eingefügt werden sie mit der Datei gespeichert; andere Programme messen dasselbe."] =
            "In “{0}” {1} measurements are not in the PDF — unless they are inserted, they are gone once “Measure” is off. Inserted as dimensions, they are saved with the file; other programs measure the same.",
        ["In die PDF einfügen"] = "Insert into the PDF",
        ["Alle in die PDF einfügen"] = "Insert all into the PDF",
        ["Zurück zum Messen"] = "Back to measuring",
        ["Nicht mehr fragen (wieder einschaltbar im Bereich „Messen“)"] = "Don’t ask again (can be switched on again in the “Measure” area)",
        ["Art der Messung"] = "Kind of measurement",
        ["Eine Lupe neben der Maus zeigt die Stelle vierfach vergrößert; beim Kalibrieren immer"] = "A magnifier beside the mouse shows the spot four times enlarged; always while calibrating",
        ["Liegt eine Linie fast waagerecht, senkrecht oder schräg im 45°-Winkel, rastet sie genau ein; Umschalt kehrt es jeweils um"] = "A line that is nearly horizontal, vertical or at 45° snaps exactly onto it; Shift turns this around",
        ["Aus: Punkte sitzen, wo geklickt wird; Alt kehrt es jeweils um"] = "Off: points sit where clicked; Alt turns it round",
        ["Klick auf eine Messung (Linie, Punkt oder Wert) wählt sie — auch eine gespeicherte Bemaßung: Punkte direkt ziehen, Strg+Klick auf die Linie der gewählten Messung fügt einen Punkt ein, Punkt anklicken und Entf entfernt ihn, Doppelklick auf einen Linienzug setzt ihn fort; Strg+Klick sonst auf eine Messung beginnt dort eine neue. Farbe, Strich, Löschen in der Leiste darüber."] =
            "Clicking a measurement (line, point or value) chooses it — a saved dimension too: drag points directly, Ctrl+click on the line of the chosen measurement puts in a point, click a point and Del takes it out, a double-click on a polyline continues it; Ctrl+click on a measurement elsewhere starts a new one there. Colour, stroke, delete in the bar above it.",
        ["Strichstärke"] = "Line width",
        ["Deckkraft der Füllung"] = "Opacity of the fill",
        ["Messung löschen"] = "Delete measurement",
        ["Die Punkte dieses Linienzugs als Bogen auswerten, oder den Bogen wieder als Linienzug"] = "Evaluate the points of this polyline as an arc, or the arc again as a polyline",
        ["Maße an jedem Stück"] = "Length at each piece",
        ["Winkel an jedem Knick"] = "Angle at each bend",
        // Messen: Darstellung (Ablaufplan 7.6 e2)
        ["Violett"] = "Violet",
        ["Farbe neuer Messungen"] = "Colour of new measurements",
        ["Maße an allen Linien"] = "Lengths at all lines",
        ["Winkel an allen Knicken"] = "Angles at all bends",
