        // Scanning (KONZEPT §5.25)
        ["1 Seite gescannt."] = "1 page scanned.",
        ["1 gescannte Seite angehängt — Strg+Z nimmt es zurück."] = "1 scanned page appended — Ctrl+Z undoes it.",
        ["Abgebrochen — {0} Seiten behalten."] = "Cancelled — {0} pages kept.",
        ["Als Bild speichern …"] = "Save as image …",
        ["Als neues Dokument übernehmen"] = "Take over as new document",
        ["An offenes Dokument anhängen"] = "Append to open document",
        ["Dem Scanner-Treiber fehlt Arbeitsspeicher."] = "The scanner driver is out of memory.",
        ["Der Scanner hat keine Bilddaten geliefert."] = "The scanner delivered no image data.",
        ["Der Scanner antwortet nicht mehr — die Verbindung wurde beendet. Schon gescannte Seiten bleiben."] = "The scanner no longer answers — the connection was ended. Pages already scanned stay.",
        ["Der Scanner-Treiber ist abgestürzt — schon gescannte Seiten bleiben. Beim nächsten Scannen wird er neu gestartet."] = "The scanner driver crashed — pages already scanned stay. It is started again for the next scan.",
        ["Der Hilfsprozess zum Scannen ließ sich nicht starten."] = "The helper process for scanning could not be started.",
        ["Der Scanner ist nicht erreichbar — ist er eingeschaltet?"] = "The scanner cannot be reached — is it switched on?",
        ["Der Name „{0}“ lässt sich im Netzwerk nicht auflösen."] = "The name “{0}” cannot be resolved in the network.",
        ["„{0}“ liegt nicht im eigenen Netzwerk. Scanner werden nur im eigenen Netzwerk angesprochen."] =
            "“{0}” is not in your own network. Scanners are only addressed in your own network.",
        ["„{0}“ ist zu groß — bitte ein Netz mit höchstens 254 Adressen, zum Beispiel 192.168.178.0."] =
            "“{0}” is too large — please a network of at most 254 addresses, for example 192.168.178.0.",
        ["„{0}“ ist kein Netz. Beispiel: 192.168.178.0"] = "“{0}” is not a network. Example: 192.168.178.0",
        ["Der Scanner hat den Auftrag angenommen, aber keine Adresse dafür genannt."] = "The scanner accepted the job but named no address for it.",
        ["Der Auftrag ist am Scanner nicht mehr vorhanden."] = "The job no longer exists at the scanner.",
        ["Der Auftrag wurde am Scanner abgebrochen."] = "The job was cancelled at the scanner.",
        ["Der Scanner hat den Auftrag abgebrochen ({0})."] = "The scanner aborted the job ({0}).",
        ["Adresse entfernen"] = "Remove address",
        ["Adresse hinzufügen"] = "Add address",
        ["Das Zertifikat von „{0}“ hat sich geändert. Wurde das Gerät zurückgesetzt oder ersetzt? Sonst könnte sich ein anderes Gerät als dieser Scanner ausgeben.\n\nBisher: {1}\nJetzt: {2}"] =
            "The certificate of “{0}” has changed. Was the device reset or replaced? Otherwise another device could be posing as this scanner.\n\nBefore: {1}\nNow: {2}",
        ["Diagnose speichern"] = "Save diagnosis",
        ["Diagnose speichern …"] = "Save diagnosis …",
        ["Die Diagnose ließ sich nicht speichern: {0}"] = "The diagnosis could not be saved: {0}",
        ["Eine Suche über ein ganzes Netz sieht für die Überwachung eines Firmennetzes wie ein Angriff aus — bitte nur in Absprache mit der IT."] =
            "To the monitoring of a company network, a search across a whole network looks like an attack — please only in agreement with IT.",
        ["Einzug arbeitet"] = "Feeder working",
        ["Es lassen sich höchstens {0} Adressen eintragen."] = "At most {0} addresses can be entered.",
        ["Es lassen sich höchstens {0} Netze eintragen."] = "At most {0} networks can be entered.",
        ["Für einen Scanner, den die Suche nicht findet: seine IP-Adresse oder sein Name im Netzwerk, wahlweise mit Port oder als http- bzw. https-Adresse"] =
            "For a scanner the search does not find: its IP address or its name in the network, optionally with port or as an http or https address",
        ["Kein Papier im Einzug"] = "No paper in the feeder",
        ["Klappe des Einzugs offen"] = "Feeder cover open",
        ["NETZWERK-SCANNER (ERWEITERT)"] = "NETWORK SCANNERS (ADVANCED)",
        ["Netz der Scanner"] = "Network of the scanners",
        ["Netz durchsuchen"] = "Search network",
        ["Netz entfernen"] = "Remove network",
        ["Netz hinzufügen"] = "Add network",
        ["Netze der Scanner (nur Firmennetz)"] = "Networks of the scanners (company network only)",
        ["Netzwerk-Scanner (erweitert)"] = "Network scanners (advanced)",
        ["Netzwerk-Scanner direkt ansprechen"] = "Address network scanners directly",
        ["Nicht vertrauen"] = "Do not trust",
        ["Nur ausfüllen, wenn Drucker und Scanner im Firmennetz in einem eigenen Netz (VLAN) liegen und die Suche sie nicht findet. Es zählen die ersten drei Teile der Adresse, zum Beispiel 192.168.178.0 — durchsucht wird dann 192.168.178.1 bis 254. Mehrere Netze mit Komma trennen."] =
            "Only fill in if printers and scanners in the company network sit in a network of their own (VLAN) and the search does not find them. The first three parts of the address count, for example 192.168.178.0 — then 192.168.178.1 to 254 are searched. Separate several networks with commas.",
        ["Ohne bestätigtes Zertifikat lässt sich dieser Scanner nicht verwenden."] = "This scanner cannot be used without a confirmed certificate.",
        ["PDF-Knead spricht Netzwerk-Scanner selbst an: Papier im Einzug, Stau und Klappe werden angezeigt, Abbrechen wirkt sofort. Aus: nur über den Scanner-Treiber des Systems."] =
            "PDF-Knead addresses network scanners itself: paper in the feeder, jams and covers are shown, cancelling acts at once. Off: only through the system's scanner driver.",
        ["Papier im Einzug"] = "Paper in the feeder",
        ["Papierstau im Einzug"] = "Paper jam in the feeder",
        ["Problem mit dem Papier — bitte nachsehen"] = "Problem with the paper — please check",
        ["Scanner-Adresse"] = "Scanner address",
        ["Speichert, was PDF-Knead zuletzt mit Netzwerk-Scannern getan hat — für die Fehlersuche. Die Datei enthält Gerätenamen und Adressen im eigenen Netz, keine Bilder."] =
            "Saves what PDF-Knead last did with network scanners — for troubleshooting. The file contains device names and addresses in your own network, no images.",
        ["Sucht in den eingetragenen Netzen nach Scannern und zeigt sie hier; mit dem grünen Haken kommen sie in die Scannerauswahl. Ein Netz dauert etwa 10 Sekunden."] =
            "Searches the entered networks for scanners and shows them here; the green check puts them into the scanner list. A network takes about 10 seconds.",
        ["Durchsucht die Netze …"] = "Searching the networks …",
        ["Gerätenamen werden ermittelt …"] = "Looking up the device names …",
        ["Ausgeblendete Scanner wieder zeigen ({0})"] = "Show hidden scanners again ({0})",
        ["Scanner aus der Liste entfernen"] = "Remove scanner from the list",
        ["Scanner aus der Liste entfernen — ein im System eingerichteter wird hier nur ausgeblendet"] = "Remove scanner from the list — one installed in the system is only hidden here",
        ["nicht erreichbar"] = "not reachable",
        ["Durchsucht die Netze … {0} %"] = "Searching the networks … {0} %",
        ["Erst ein Netz eintragen, zum Beispiel 192.168.178.0."] = "Enter a network first, for example 192.168.178.0.",
        ["Haken: dieser Scanner kommt in die Scannerauswahl"] = "Check: this scanner goes into the scanner list",
        ["Kein Scanner gefunden."] = "No scanner found.",
        ["bei der letzten Suche nicht gefunden"] = "not found by the last search",
        ["{0} ({1}) in die Scannerauswahl"] = "{0} ({1}) in the scanner list",
        ["{0} Scanner gefunden — mit dem Haken kommen sie in die Scannerauswahl."] = "{0} scanner(s) found — the check puts them into the scanner list.",
        ["Vertrauen"] = "Trust",
        ["Zertifikat des Scanners"] = "Scanner certificate",
        ["z. B. 192.168.178.0"] = "e.g. 192.168.178.0",
        ["z. B. 192.168.178.20"] = "e.g. 192.168.178.20",
        ["„{0}“ ist keine Scanner-Adresse. Beispiele: 192.168.178.20, scanner.local, https://192.168.178.20"] =
            "“{0}” is not a scanner address. Examples: 192.168.178.20, scanner.local, https://192.168.178.20",
        ["„{0}“ weist sich mit einem eigenen Zertifikat aus. Fingerabdruck:\n{1}\n\nWer diesem Gerät vertraut, verbindet sich künftig nur noch mit genau diesem Zertifikat. Sonst wird der Scanner über den Scanner-Treiber des Systems angesprochen."] =
            "“{0}” identifies itself with a certificate of its own. Fingerprint:\n{1}\n\nTrusting this device means connecting only to exactly this certificate from now on. Otherwise the scanner is addressed through the system's scanner driver.",
        ["Der Scanner nennt eine ungültige Adresse."] = "The scanner names an invalid address.",
        ["Der Scanner leitet auf eine andere Adresse um — das wird aus Sicherheitsgründen nicht befolgt."] =
            "The scanner redirects to another address — for safety this is not followed.",
        ["Der Scanner antwortet nicht rechtzeitig."] = "The scanner does not answer in time.",
        ["Der Scanner hat eine zu große Antwort geschickt."] = "The scanner sent an answer that is too large.",
        ["Der Scanner hat eine unverständliche Antwort geschickt."] = "The scanner sent an answer that cannot be understood.",
        ["Der Scanner verlangt eine Anmeldung — das unterstützt PDF-Knead noch nicht."] = "The scanner asks for a login — PDF-Knead does not support that yet.",
        ["Der Scanner weist sich mit einem Zertifikat aus, das noch nicht bestätigt ist."] = "The scanner identifies itself with a certificate that has not been confirmed yet.",
        ["Das Zertifikat des Scanners hat sich geändert. Wurde das Gerät zurückgesetzt oder ersetzt? Sonst könnte sich ein anderes Gerät als dieser Scanner ausgeben."] =
            "The scanner's certificate has changed. Was the device reset or replaced? Otherwise another device could be posing as this scanner.",
        ["Der Scanner ist gerade belegt — vielleicht von einem anderen Programm."] = "The scanner is busy — perhaps another program is using it.",
        ["Der Scanner kann das nicht."] = "The scanner cannot do that.",
        ["Der Scanner lehnt die Einstellung ab."] = "The scanner refuses this setting.",
        ["Der Scanner liefert ein unbekanntes Bildformat."] = "The scanner delivers an unknown image format.",
        ["Der Scanner liefert ein unvollständiges Farbbild."] = "The scanner delivers an incomplete colour image.",
        ["Der Scanner meldet einen Fehler ({0})."] = "The scanner reports an error ({0}).",
        ["Die Seite wäre zu groß — bitte eine kleinere Auflösung oder Fläche wählen."] = "The page would be too large — please choose a lower resolution or a smaller area.",
        ["Die Seiten als neues, noch nicht gespeichertes Dokument in PDF-Knead öffnen"] = "Open the pages as a new, not yet saved document in PDF-Knead",
        ["Die Seiten ans Ende des geöffneten Dokuments setzen — Strg+Z nimmt es zurück"] = "Put the pages at the end of the open document — Ctrl+Z undoes it",
        ["Die Verbindung zum Scanner ist gestört."] = "The connection to the scanner is disturbed.",
        ["Eine Abdeckung des Scanners ist offen."] = "A cover of the scanner is open.",
        ["Einzug"] = "Feeder",
        ["Einzug beidseitig"] = "Feeder, both sides",
        ["Flachbett"] = "Flatbed",
        ["Flachbett oder Einzug — der Einzug bietet oft weniger Auflösung als das Flachbett"] = "Flatbed or feeder — the feeder often offers less resolution than the flatbed",
        ["Ganze Fläche"] = "Whole area",
        ["Gescannte Seiten ({0})"] = "Scanned pages ({0})",
        ["Gewählte Seiten löschen (Entf)"] = "Delete the selected pages (Del)",
        ["Gewählte Seiten um 90° nach links drehen"] = "Rotate the selected pages 90° to the left",
        ["Gewählte Seiten um 90° nach rechts drehen"] = "Rotate the selected pages 90° to the right",
        ["Im Einzug liegt kein Papier."] = "There is no paper in the feeder.",
        ["Kacheln"] = "Tiles",
        ["Kein Scanner"] = "No scanner",
        ["Kein Scanner gefunden. Ist er eingeschaltet und angeschlossen bzw. im selben Netzwerk?"] = "No scanner found. Is it switched on and connected, or in the same network?",
        ["Kein Zugriff auf den Scanner — fehlen die Rechte?"] = "No access to the scanner — are permissions missing?",
        ["Keine Seite gescannt."] = "No page scanned.",
        ["Stapel {0}: {1} Blätter beidseitig gescannt."] = "Stack {0}: {1} sheets scanned on both sides.",
        ["{0} dpi bietet diese Quelle nicht an, {1} dpi gewählt."] = "This source does not offer {0} dpi, {1} dpi chosen.",
        ["{0} leere Seiten weggelassen."] = "{0} blank pages left out.",
        ["{0} Scanprofile exportiert: {1}"] = "{0} scan profiles exported: {1}",
        ["{0} Scanprofile gelöscht."] = "{0} scan profiles deleted.",
        ["{0} Scanprofile importiert."] = "{0} scan profiles imported.",
        ["{0} Scanprofile löschen?"] = "Delete {0} scan profiles?",
        ["Stapel {0}: {1} Vorderseiten, aber {2} Rückseiten — bitte die Reihenfolge prüfen oder „Rückseiten neu scannen“."] =
            "Stack {0}: {1} fronts but {2} backs — please check the order or “Scan backs again”.",
        ["Stapel {0}: {1} Vorderseiten gescannt. Jetzt die Rückseiten: den Stapel aus der Ablage nehmen, ohne die Reihenfolge zu ändern, wie eine Buchseite umdrehen und so in den Einzug legen wie vorher — Oberkante voran. Dann „Rückseiten scannen“ drücken."] =
            "Stack {0}: {1} fronts scanned. Now the backs: take the stack from the tray without changing its order, turn it over like the page of a book and put it into the feeder as before — top edge first. Then press “Scan backs”.",
        ["Stapel {0}: Rückseiten neu scannen — den Stapel so in den Einzug legen wie zuletzt für die Rückseiten (Rückseiten nach oben, Oberkante voran). Dann „Rückseiten scannen“ drücken; die bisherigen Rückseiten bleiben, bis die neuen da sind."] =
            "Stack {0}: scan the backs again — put the stack into the feeder as last time for the backs (backs up, top edge first). Then press “Scan backs”; the backs scanned before stay until the new ones are there.",
        ["Bisherige behalten"] = "Keep the previous ones",
        ["Seiten werden einsortiert … einen Moment, bevor Sie weitermachen."] = "Sorting the pages … one moment before you go on.",
        ["Die Vorderseiten dieses Stapels um 180° drehen — wenn er verkehrt herum eingelegt war; legen Sie ihn für die Rückseiten genauso ein, kommen auch sie gleich richtig"] =
            "Turn the fronts of this stack by 180° — when it was put in upside down; put it in the same way for the backs and they come right at once",
        ["Diese Seite ist begradigt — klicken, um sie wie gescannt zu lassen"] = "This page is straightened — click to leave it as scanned",
        ["Begradigen für diese Seite verworfen — klicken, um sie wieder zu begradigen"] = "Straightening discarded for this page — click to straighten it again",
        ["Stapel {0} · 1 Seite"] = "Stack {0} · 1 page",
        ["Stapel {0} · {1} Seiten"] = "Stack {0} · {1} pages",
        ["Stapel {0} · beidseitig · 1 Seite"] = "Stack {0} · both sides · 1 page",
        ["Stapel {0} · beidseitig · {1} Seiten"] = "Stack {0} · both sides · {1} pages",
        ["Rückseiten um 180° drehen"] = "Turn backs by 180°",
        ["Vorderseiten um 180° drehen"] = "Turn fronts by 180°",
        ["Rückseiten andersherum zuordnen"] = "Pair backs the other way round",
        ["Rückseiten neu scannen"] = "Scan backs again",
        ["Alle Rückseiten dieses Stapels um 180° drehen — wenn sie auf dem Kopf stehen; gemerkt wird, wie die Rückseiten zu den Vorderseiten liegen"] =
            "Turn all backs of this stack by 180° — when they are upside down; how the backs lie against the fronts is remembered",
        ["Alle Vorderseiten dieses Stapels um 180° drehen — wenn der Stapel verkehrt herum eingelegt war; gilt nur für diesen Stapel"] =
            "Turn all fronts of this stack by 180° — when the stack was put in upside down; only for this stack",
        ["Die Rückseiten dieses Stapels noch einmal scannen (Stau, falsch gewendet, ein Blatt fehlt) — die Vorderseiten bleiben"] =
            "Scan the backs of this stack once more (jam, turned the wrong way, a sheet missing) — the fronts stay",
        ["Die Rückseiten in umgekehrter Reihenfolge den Vorderseiten zuordnen — je nach Papierweg des Scanners; wird im Profil gemerkt"] =
            "Pair the backs with the fronts in reverse order — depending on the scanner's paper path; remembered in the profile",
        ["Lage-Korrektur ausblenden"] = "Hide the position correction",
        ["Ausblenden — die Seiten bleiben, wie sie sind"] = "Hide — the pages stay as they are",
        ["Lage-Korrektur manueller Duplex-Scan"] = "Position correction of the manual duplex scan",
        ["Stehen Seiten dieses Stapels auf dem Kopf oder an der falschen Stelle, hier korrigieren — wie die Rückseiten liegen, wird gemerkt. Mit dem nächsten Scan ist der Stapel fertig; danach nur noch über „Drehen“ an ausgewählten Seiten."] =
            "If pages of this stack are upside down or in the wrong place, correct it here — how the backs lie is remembered. With the next scan the stack is done; after that only with “Rotate” on selected pages.",
        ["1 leere Seite weggelassen."] = "1 blank page left out.",
        ["1 Scanprofil exportiert: {0}"] = "1 scan profile exported: {0}",
        ["1 Scanprofil importiert."] = "1 scan profile imported.",
        ["manueller Duplex"] = "manual duplex",
        ["Manueller Duplex"] = "Manual duplex",
        ["Bereit: {0} — {1}"] = "Ready: {0} — {1}",
        ["Das lässt sich nicht rückgängig machen."] = "This cannot be undone.",
        ["Das Profil ließ sich nicht speichern: {0}"] = "The profile could not be saved: {0}",
        ["Der Scanner des Profils ist nicht da ({0}) — die übrigen Einstellungen gelten."] = "The profile's scanner is not there ({0}) — the other settings apply.",
        ["Die angekreuzten Profile in eine Datei schreiben — ist keins angekreuzt, alle"] = "Write the ticked profiles into a file — all of them if none is ticked",
        ["Die angekreuzten Profile löschen"] = "Delete the ticked profiles",
        ["Die Datei enthält keine Scanprofile von PDF-Knead."] = "The file contains no PDF-Knead scan profiles.",
        ["Die Datei enthält zu viele Scanprofile (höchstens {0})."] = "The file contains too many scan profiles (at most {0}).",
        ["Die Datei ist zu groß für Scanprofile."] = "The file is too large for scan profiles.",
        ["Die Datei ließ sich nicht lesen: {0}"] = "The file could not be read: {0}",
        ["Die Einstellungen links unter einem Namen speichern, um sie oben unter „Profil“ wieder zu wählen"] = "Save the settings on the left under a name, to choose them again under “Profile” at the top",
        ["Die Scanprofile ließen sich nicht exportieren: {0}"] = "The scan profiles could not be exported: {0}",
        ["Die Scanprofile ließen sich nicht löschen: {0}"] = "The scan profiles could not be deleted: {0}",
        ["Die Scanprofile stammen aus einer neueren Version von PDF-Knead — bitte das Programm aktualisieren."] = "The scan profiles come from a newer version of PDF-Knead — please update the program.",
        ["Ein Profil „{0}“ gibt es schon. „Ersetzen“ ersetzt es."] = "A profile “{0}” already exists. “Replace” replaces it.",
        ["Ein Scanprofil merkt sich Scanner, Quelle, Auflösung, Farbe, Format und die Einstellungen zu den Seiten. Angelegt wird es im Fenster „Scannen“ mit „Profil speichern“; hier lässt es sich in eine Datei exportieren und auf einem anderen Rechner importieren."] = "A scan profile remembers scanner, source, resolution, colour, format and the page settings. It is created in the “Scan” window with “Save profile”; here it can be exported into a file and imported on another computer.",
        ["Ersetzen"] = "Replace",
        ["Es sind höchstens {0} Scanprofile möglich."] = "At most {0} scan profiles are possible.",
        ["Beidseitig scannen mit einem Einzug, der nur eine Seite liest: Erst scannt PDF-Knead alle Vorderseiten. Dann nehmen Sie den Stapel aus der Ablage, wenden ihn wie eine Buchseite und legen ihn wieder ein — die Rückseiten werden gescannt und Blatt für Blatt hinter ihre Vorderseiten sortiert. Stehen Seiten auf dem Kopf oder an der falschen Stelle, korrigiert die Leiste „Lage-Korrektur“ das; wie die Rückseiten liegen, merkt sich das Profil. Leere Seiten fallen erst nach dem Einsortieren weg. Jeder Stapel bleibt eine eigene Gruppe in den Kacheln."] =
            "Scanning both sides with a feeder that reads one side only: first PDF-Knead scans all fronts. Then take the stack from the tray, turn it over like the page of a book and put it in again — the backs are scanned and sorted sheet by sheet behind their fronts. If pages are upside down or in the wrong place, the “Position correction” bar corrects it; the profile remembers how the backs lie. Blank pages are left out only after sorting. Every stack stays a group of its own in the tiles.",
        ["Gespeicherte Einstellungen für Scanner, Quelle, Auflösung, Farbe, Format und Seiten — „Profil speichern“ legt eins an, Datei → Scanprofile exportiert und importiert sie"] = "Saved settings for scanner, source, resolution, colour, format and pages — “Save profile” creates one, File → Scan profiles exports and imports them",
        ["Gespeicherte Einstellungen zum Scannen exportieren, importieren oder löschen"] = "Export, import or delete saved scan settings",
        ["GESPEICHERTE PROFILE"] = "SAVED PROFILES",
        ["Importieren …"] = "Import …",
        ["Keine neuen Scanprofile — alle gibt es schon."] = "No new scan profiles — all of them exist already.",
        ["Keine Rückseiten scannen — die Vorderseiten bleiben, wie sie sind; beim erneuten Scannen der Rückseiten bleiben die bisherigen"] =
            "Scan no backs — the fronts stay as they are; when scanning the backs again, the previous ones stay",
        ["Leer bis {0:0.##} % bedeckt"] = "Blank up to {0:0.##} % covered",
        ["Zoom der Vorschau"] = "Zoom of the preview",
        ["Vorschau vergrößern — auch mit Strg+Mausrad; die Seite mit der Maus frei verschieben"] = "Enlarge the preview — also with Ctrl+mouse wheel; drag the page freely with the mouse",
        ["◧  Vorher / Nachher"] = "◧  Before / after",
        ["Vorher / Nachher"] = "Before / after",
        ["Vergleich mit Trennlinie: links vorher (wie gescannt, nur begradigt), rechts nach der Nachbearbeitung. Die Linie mit der Maus über die Seite ziehen; Zoom und Ausschnitt bleiben gleich."] = "Comparison with a dividing line: left before (as scanned, only straightened), right after the processing. Drag the line across the page with the mouse; zoom and section stay the same.",
        ["Ziehen verschiebt die Seite (bis zur Mitte ihrer Ränder), Strg+Mausrad zoomt, Doppelklick zeigt die ganze Seite"] = "Dragging moves the page (until its edges reach the middle), Ctrl+mouse wheel zooms, a double-click shows the whole page",
        ["Ganze Seite zeigen"] = "Show the whole page",
        ["Begradigen"] = "Straighten",
        ["Begradigung verwerfen"] = "Discard straightening",
        ["Begradigung wieder anwenden"] = "Apply straightening again",
        ["Den von Hand gesetzten Winkel vergessen — die Seite wird wieder automatisch begradigt"] = "Forget the angle set by hand — the page is straightened automatically again",
        ["Die Seite am Gitter ausrichten — Pfeiltasten 0,1°, Bild auf/ab 1°, Enter übernimmt, Esc bricht ab"] = "Align the page with the grid — arrow keys 0.1°, page up/down 1°, Enter keeps, Esc cancels",
        ["Dunkle Ränder wegschneiden — Kante des Glases, Schatten des Deckels, dunkler Deckel um ein kleineres Blatt"] = "Cut away dark borders — edge of the glass, shadow of the lid, a dark lid around a smaller sheet",
